/* DAWAH X — ahmad, অধ্যায় 128 · খণ্ড 128 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][128]=[[25401,25401,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏وَهْبٍ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَهِيَ ‏ ‏تَخْتَمِرُ ‏ ‏فَقَالَ ‏ ‏لَيَّةً ‏ ‏لَا ‏ ‏لَيَّتَيْنِ ‏","","",""],[25402,25402,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ تَحْتَكِمُونَ إِلَيَّ وَإِنَّمَا أَنَا بَشَرٌ وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ ‏ ‏أَلْحَنَ ‏ ‏بِحُجَّتِهِ مِنْ بَعْضٍ وَإِنَّمَا ‏ ‏أَقْضِي ‏ ‏بَيْنَكُمْ عَلَى نَحْوِ مَا أَسْمَعُ فَمَنْ قَضَيْتُ لَهُ مِنْ حَقِّ أَخِيهِ شَيْئًا فَلَا يَأْخُذْهُ فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنْ النَّارِ يَأْتِي بِهَا يَوْمَ الْقِيَامَةِ ‏","","",""],[25403,25403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الْحَمِيدِ بْنَ عَبْدِ اللَّهِ بْنِ أَبِي عَمْرٍو ‏ ‏وَالْقَاسِمَ ‏ ‏أَخْبَرَاهُ أَنَّهُمَا سَمِعَا ‏ ‏أَبَا بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏يُخْبِرُ أَنَّ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ أَنَّها ‏ ‏لَمَّا قَدِمَتْ ‏ ‏الْمَدِينَةَ ‏ ‏أَخْبَرَتْهُمْ أَنَّهَا ‏ ‏ابْنَةُ أَبِي أُمَيَّةَ بْنِ الْمُغِيرَةِ ‏ ‏فَكَذَّبُوهَا وَيَقُولُونَ مَا أَكْذَبَ الْغَرَائِبَ حَتَّى أَنْشَأَ نَاسٌ مِنْهُمْ إِلَى الْحَجِّ فَقَالُوا مَا تَكْتُبِينَ إِلَى أَهْلِكِ فَكَتَبَتْ مَعَهُمْ فَرَجَعُوا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏يُصَدِّقُونَهَا فَازْدَادَتْ عَلَيْهِمْ ‏ ‏كَرَامَةً ‏ ‏قَالَتْ فَلَمَّا وَضَعْتُ ‏ ‏زَيْنَبَ ‏ ‏جَاءَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَطَبَنِي فَقُلْتُ مَا مِثْلِي نُكِحَ أَمَّا أَنَا فَلَا وَلَدَ فِيَّ وَأَنَا غَيُورٌ وَذَاتُ عِيَالٍ فَقَالَ أَنَا أَكْبَرُ مِنْكِ وَأَمَّا الْغَيْرَةُ فَيُذْهِبُهَا اللَّهُ عَزَّ وَجَلَّ وَأَمَّا الْعِيَالُ فَإِلَى اللَّهِ وَرَسُولِهِ فَتَزَوَّجَهَا فَجَعَلَ يَأْتِيهَا فَيَقُولُ أَيْنَ ‏ ‏زُنَابُ ‏ ‏حَتَّى جَاءَ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏يَوْمًا ‏ ‏فَاخْتَلَجَهَا ‏ ‏وَقَالَ هَذِهِ تَمْنَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ تُرْضِعُهَا فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيْنَ ‏ ‏زُنَابُ ‏ ‏فَقَالَتْ ‏ ‏قَرِيبَةُ ابْنَةِ أَبِي أُمَيَّةَ ‏ ‏وَوَافَقَهَا عِنْدَهَا أَخَذَهَا ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي آتِيكُمْ اللَّيْلَةَ قَالَتْ فَقُمْتُ فَأَخْرَجْتُ حَبَّاتٍ مِنْ شَعِيرٍ كَانَتْ فِي ‏ ‏جَرٍّ ‏ ‏وَأَخْرَجْتُ شَحْمًا ‏ ‏فَعَصَدْتُهُ ‏ ‏لَهُ قَالَتْ فَبَاتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَصْبَحَ فَقَالَ حِينَ أَصْبَحَ ‏ ‏إِنَّ لَكِ عَلَى أَهْلِكِ ‏ ‏كَرَامَةً ‏ ‏فَإِنْ شِئْتِ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ فَإِنْ أُسَبِّعْ لَكِ أُسَبِّعْ لِنِسَائِي ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الْحَمِيدِ بْنَ عَبْدِ اللَّهِ بْنِ أَبِي عَمْرٍو ‏ ‏وَالْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏أَخْبَرَاهُ أَنَّهُمَا سَمِعَا ‏ ‏أَبَا بَكْرِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ قَالَتْ فَوَضَعْتُ ثِفَالِي فَأَخْرَجْتُ حَبَّاتٍ مِنْ الشَّعِيرِ ‏","","",""],[25404,25404,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَقَالَتْ لَهُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أَصْحَابِي مَنْ لَا يَرَانِي بَعْدَ أَنْ يُفَارِقَنِي ‏ ‏قَالَ ‏ ‏فَأَتَى ‏ ‏عُمَرَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ قَالَ فَأَتَاهَا ‏ ‏عُمَرُ ‏ ‏فَقَالَ أُذَكِّرُكِ اللَّهَ أَمِنْهُمْ أَنَا قَالَتْ اللَّهُمَّ لَا وَلَنْ ‏ ‏أُبْلِيَ ‏ ‏أَحَدًا بَعْدَكَ ‏","","",""],[25405,25405,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَسَارٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ أَنَّهَا ‏ ‏قَرَّبَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَنْبًا مَشْوِيًّا ‏ ‏فَأَكَلَ مِنْهُ ثُمَّ قَامَ إِلَى الصَّلَاةِ وَلَمْ يَتَوَضَّأْ ‏","","",""],[25406,25406,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَالْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏إِنْ شِئْتِ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ وَإِنْ أُسَبِّعْ لَكِ أُسَبِّعْ لِنِسَائِي ‏","","",""],[25407,25407,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُدْرِكُهُ الْفَجْرُ وَهُوَ ‏ ‏جُنُبٌ ‏ ‏مِنْ أَهْلِهِ ثُمَّ يَغْتَسِلُ فَيَصُومُ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏زَوْجَتَيْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25408,25408,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ مَمْلَكٍ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ قَالَتْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْعِشَاءَ الْآخِرَةَ ثُمَّ يُسَبِّحُ ثُمَّ ‏ ‏يُصَلِّي بَعْدَهَا مَا شَاءَ اللَّهُ عَزَّ وَجَلَّ مِنْ اللَّيْلِ ثُمَّ يَنْصَرِفُ فَيَرْقُدُ مِثْلَ مَا ‏ ‏يُصَلِّي ثُمَّ يَسْتَيْقِظُ مِنْ نَوْمَتِهِ تِلْكَ فَيُصَلِّي مِثْلَ مَا نَامَ وَصَلَاتُهُ تِلْكَ الْآخِرَةُ تَكُونُ إِلَى الصُّبْحِ ‏","","",""],[25409,25409,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَجَبَةَ ‏ ‏خَصْمٍ عِنْدَ بَابِ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ فَخَرَجَ إِلَيْهِمْ فَقَالَ ‏ ‏إِنَّكُمْ تَخْتَصِمُونَ وَإِنَّمَا أَنَا بَشَرٌ وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَعْلَمَ بِحُجَّتِهِ مِنْ بَعْضٍ فَأَقْضِيَ لَهُ بِمَا أَسْمَعُ مِنْهُ فَأَظُنُّهُ صَادِقًا فَمَنْ قَضَيْتُ لَهُ بِشَيْءٍ مِنْ حَقِّ أَخِيهِ فَإِنَّهَا قِطْعَةٌ مِنْ النَّارِ فَلْيَأْخُذْهَا أَوْ لِيَدَعْهَا ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ ابْنَةَ أَبِي سَلَمَةَ ‏ ‏أَخْبَرَتْهُ أَنَّ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهَا ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سَمِعَ خُصُومَةً بِبَابِ حُجْرَتِهِ فَخَرَجَ إِلَيْهِمْ فَقَالَ إِنَّمَا أَنَا بَشَرٌ فَذَكَرَ مَعْنَاهُ ‏","","",""],[25410,25410,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ امْرَأَةً أَهْدَتْ لَهَا رِجْلَ شَاةٍ تُصُدِّقَ عَلَيْهَا بِهَا فَأَمَرَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تَقْبَلَهَا ‏","","",""],[25411,25411,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏نَبْهَانُ ‏ ‏مُكَاتَبُ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَ إِنِّي ‏ ‏لَأَقُودُ ‏ ‏بِهَا ‏ ‏بِالْبَيْدَاءِ ‏ ‏أَوْ قَالَ ‏ ‏بِالْأَبْوَاءِ ‏ ‏فَقَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا كَانَ عِنْدَ ‏ ‏الْمُكَاتَبِ ‏ ‏مَا يُؤَدِّي فَاحْتَجِبِي مِنْهُ ‏","","",""],[25412,25412,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَدْرَكَهُ الصُّبْحُ جُنُبًا فَلَا صَوْمَ لَهُ قَالَ فَانْطَلَقْتُ أَنَا وَأَبِي فَدَخَلْنَا عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَائِشَةَ ‏ ‏فَسَأَلْنَاهُمَا عَنْ ذَلِكَ فَأَخْبَرَتَانَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ غَيْرِ حُلُمٍ ثُمَّ يَصُومُ فَلَقِينَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَحَدَّثَهُ أَبِي فَتَلَوَّنَ وَجْهُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏ثُمَّ قَالَ هَكَذَا حَدَّثَنِي ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏وَهُنَّ أَعْلَمُ ‏","","",""],[25413,25413,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَحَدَّثَنِي ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏امْرَأَةَ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏الْمَرْأَةُ ‏ ‏تَرَى زَوْجَهَا فِي الْمَنَامِ ‏ ‏يَقَعُ ‏ ‏عَلَيْهَا أَعَلَيْهَا غُسْلٌ قَالَ نَعَمْ إِذَا رَأَتْ ‏ ‏بَلَلًا فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏أَوَتَفْعَلُ ذَلِكَ فَقَالَ ‏ ‏تَرِبَتْ ‏ ‏يَمِينُكِ أَنَّى يَأْتِي شَبَهُ الْخُؤُولَةِ إِلَّا مِنْ ذَلِكِ أَيُّ ‏ ‏النُّطْفَتَيْنِ ‏ ‏سَبَقَتْ إِلَى الرَّحِمِ غَلَبَتْ عَلَى الشَّبَهِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ تَرِبَ جَبِينُكِ ‏","","",""],[25414,25414,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ هَلْ لَكَ فِي أُخْتِي ‏ ‏ابْنَةِ أَبِي سُفْيَانَ ‏ ‏قَالَ فَأَفْعَلُ مَاذَا قَالَتْ تَنْكِحُهَا قَالَ وَذَاكَ أَحَبُّ إِلَيْكِ قَالَتْ نَعَمْ لَسْتُ لَكَ ‏ ‏بِمُخْلِيَةٍ ‏ ‏وَأَحَبُّ مَنْ شَرِكَنِي فِي الْخَيْرِ أُخْتِي قَالَ ‏ ‏إِنَّهَا لَا تَحِلُّ لِي قُلْتُ فَإِنَّهُ بَلَغَنِي أَنَّكَ تَخْطُبُ ‏ ‏دُرَّةَ ابْنَةَ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏ابْنَةُ أُمِّ سَلَمَةَ ‏ ‏قَالَتْ نَعَمْ قَالَ فَوَاللَّهِ لَوْ لَمْ تَكُنْ ‏ ‏رَبِيبَتِي ‏ ‏فِي حِجْرِي لَمَا حَلَّتْ لِي إِنَّهَا ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ أَرْضَعَتْنِي وَأَبَاهَا ‏ ‏ثُوَيْبَةُ ‏ ‏فَلَا تَعْرِضْنَ عَلَيَّ بَنَاتِكُنَّ وَلَا أَخَوَاتِكُنَّ ‏","","",""],[25415,25415,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏طَلْحَةُ بْنُ يَحْيَى ‏ ‏قَالَ ‏ ‏زَعَمَ لِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏أَرْسَلَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏يَسْأَلُهَا هَلْ صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الْعَصْرِ شَيْئًا قَالَتْ أَمَّا عِنْدِي فَلَا وَلَكِنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏أَخْبَرَتْنِي أَنَّهُ فَعَلَ ذَلِكَ فَأَرْسِلْ إِلَيْهَا فَاسْأَلْهَا فَأَرْسَلَ إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَقَالَتْ نَعَمْ دَخَلَ عَلَيَّ بَعْدَ الْعَصْرِ فَصَلَّى سَجْدَتَيْنِ قُلْتُ يَا نَبِيَّ اللَّهِ ‏ ‏أُنْزِلَ عَلَيْكَ فِي هَاتَيْنِ السَّجْدَتَيْنِ قَالَ لَا وَلَكِنْ صَلَّيْتُ الظُّهْرَ فَشُغِلْتُ فَاسْتَدْرَكْتُهَا بَعْدَ الْعَصْرِ ‏","","",""],[25416,25416,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْحَسَنُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كُلِّ مُسْكِرٍ ‏ ‏وَمُفْتِرٍ ‏","","",""],[25417,25417,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعْدُ بْنُ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ كَثِيرٍ ‏ ‏عَنِ ‏ ‏ابْنِ سَفِينَةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ ‏ ‏أْجُرْنِي ‏ ‏فِي مُصِيبَتِي وَاخْلُفْنِي خَيْرًا مِنْهَا إِلَّا ‏ ‏أَجَرَهُ ‏ ‏اللَّهُ فِي مُصِيبَتِهِ وَخَلَفَ لَهُ خَيْرًا مِنْهَا ‏ ‏قَالَتْ ‏ ‏فَلَمَّا تُوُفِّيَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏قُلْتُ مَنْ خَيْرٌ مِنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ثُمَّ عَزَمَ اللَّهُ عَزَّ وَجَلَّ لِي فَقُلْتُهَا اللَّهُمَّ ‏ ‏أْجُرْنِي ‏ ‏فِي مُصِيبَتِي وَاخْلُفْ لِي خَيْرًا مِنْهَا قَالَتْ فَتَزَوَّجْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25418,25418,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ ابْنَةِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏ذُيُولِ ‏ ‏النِّسَاءِ فَقَالَ شِبْرًا فَقُلْتُ إِذَنْ تَخْرُجَ أَقْدَامُهُنَّ يَا رَسُولَ اللَّهِ قَالَ فَذِرَاعٌ لَا تَزِدْنَ عَلَيْهِ ‏","","",""],[25419,25419,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏قَالَ ‏ ‏دَخَلَ نَاسٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَقَالُوا يَا أُمَّ الْمُؤْمِنِينَ حَدِّثِينَا عَنْ سِرِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ سِرُّهُ وَعَلَانِيَتُهُ سَوَاءً ثُمَّ نَدِمْتُ فَقُلْتُ أَفْشَيْتُ سِرَّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَلَمَّا دَخَلَ أَخْبَرَتْهُ فَقَالَ أَحْسَنْتِ ‏","","",""],[25420,25420,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ مُظَفَّرُ بْنُ مُدْرِكٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏عَنْ ‏ ‏مُسَّةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏النُّفَسَاءُ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقْعُدُ بَعْدَ ‏ ‏نِفَاسِهَا ‏ ‏أَرْبَعِينَ يَوْمًا ‏ ‏أَوْ أَرْبَعِينَ لَيْلَةً ‏ ‏قَالَتْ وَكُنَّا نَطْلِي عَلَى وُجُوهِنَا ‏ ‏الْوَرْسَ ‏ ‏مِنْ ‏ ‏الْكَلَفِ ‏","","",""],[25421,25421,"","","‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا ‏ ‏سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الذَّهَبِ يُرْبَطُ بِهِ أَوْ يُرْبَطُ بِهِ ‏ ‏الْمِسْكُ ‏ ‏قَالَ ‏ ‏اجْعَلِيهِ فِضَّةً ‏ ‏وَصَفِّرِيهِ ‏ ‏بِشَيْءٍ مِنْ زَعْفَرَانٍ ‏","","",""],[25422,25422,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏هُنَيْدَةُ الْخُزَاعِيُّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَسَأَلْتُهَا عَنْ الصِّيَامِ فَقَالَتْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنِي أَنْ أَصُومَ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ أَوَّلُهَا ‏ ‏الِاثْنَيْنِ وَالْجُمُعَةُ وَالْخَمِيسُ ‏","","",""],[25423,25423,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ ‏ ‏بِخَمْسٍ ‏ ‏أَوْ سَبْعٍ ‏ ‏لَا يَفْصِلُ بَيْنَهُنَّ بِكَلَامٍ وَلَا تَسْلِيمٍ ‏","","",""],[25424,25424,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏بَنِي أَبِي سَلَمَةَ ‏ ‏فِي حِجْرِي وَلَيْسَ لَهُمْ شَيْءٌ إِلَّا مَا أَنْفَقْتُ عَلَيْهِمْ وَلَسْتُ بِتَارِكَتِهِمْ كَذَا وَلَا كَذَا أَفَلِي أَجْرٌ إِنْ أَنْفَقْتُ عَلَيْهِمْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْفِقِي عَلَيْهِمْ فَإِنَّ لَكِ أَجْرَ مَا أَنْفَقْتِ عَلَيْهِمْ ‏","","",""],[25425,25425,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏ابْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَفِي مَوْضِعٍ آخَرَ ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْهَا عَنْ الرَّجُلِ يَأْتِي امْرَأَتَهُ ‏ ‏مُجَبِّيَةً ‏ ‏فَسَأَلَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ { ‏نِسَاؤُكُمْ ‏ ‏حَرْثٌ ‏ ‏لَكُمْ فَأْتُوا ‏ ‏حَرْثَكُمْ ‏ ‏أَنَّى شِئْتُمْ ‏} ‏صِمَامًا وَاحِدًا ‏","","",""],[25426,25426,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏هِنْدِ ابْنَةِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ مَكَثَ قَلِيلًا وَكَانُوا يَرَوْنَ أَنَّ ذَلِكَ كَيْمَا ‏ ‏يَنْفُذُ ‏ ‏النِّسَاءُ قَبْلَ الرِّجَالِ ‏","","",""],[25427,25427,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بَعْدَ الْعَصْرِ قَطُّ إِلَّا مَرَّةً وَاحِدَةً جَاءَهُ نَاسٌ بَعْدَ الظُّهْرِ فَشَغَلُوهُ فِي شَيْءٍ فَلَمْ يُصَلِّ بَعْدَ الظُّهْرِ شَيْئًا حَتَّى صَلَّى الْعَصْرَ قَالَتْ فَلَمَّا صَلَّى الْعَصْرَ دَخَلَ بَيْتِي فَصَلَّى رَكْعَتَيْنِ ‏","","",""],[25428,25428,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُهَا وَهُوَ صَائِمٌ وَكَانَا يَغْتَسِلَانِ فِي إِنَاءٍ وَاحِدٍ ‏","","",""],[25429,25429,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْكُمْ وَأَنْتُمْ أَشَدُّ تَعْجِيلًا لِلْعَصْرِ مِنْهُ ‏","","",""],[25430,25430,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏أَخِي ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ غَيْرِ احْتِلَامٍ ثُمَّ يَصُومُ يَوْمَهُ ‏ ‏قَالَ ‏ ‏فَتَرَكَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فُتْيَاهُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ أَبِي أُمَيَّةَ ‏ ‏أَخِي ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏مِثْلَهُ ‏","","",""],[25431,25431,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَالِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَمَّارٍ ‏ ‏تَقْتُلُكَ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏","","",""],[25432,25432,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْحَارِثِ ‏ ‏عَنْ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ فَقَالَ كُنَّا عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏فَحَدَّثَ عَنْ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُصَلِّيهِمَا فَأَرْسَلَ ‏ ‏مُعَاوِيَةُ ‏ ‏إِلَى ‏ ‏عَائِشَةَ ‏ ‏وَأَنَا فِيهِمْ فَسَأَلْنَاهَا فَقَالَتْ لَمْ أَسْمَعْهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ حَدَّثَتْنِي ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَسَأَلْتُهَا فَحَدَّثَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ ثُمَّ أُتِيَ بِشَيْءٍ فَجَعَلَ يَقْسِمُهُ حَتَّى حَضَرَتْ صَلَاةُ الْعَصْرِ فَقَامَ فَصَلَّى الْعَصْرَ ثُمَّ صَلَّى بَعْدَهَا رَكْعَتَيْنِ فَلَمَّا صَلَّاهَا قَالَ ‏ ‏هَاتَانِ الرَّكْعَتَانِ كُنْتُ ‏ ‏أُصَلِّيهِمَا بَعْدَ الظُّهْرِ فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏وَلَقَدْ حَدَّثْتُهَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُمَا قَالَ فَأَتَيْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏فَأَخْبَرْتُهُ بِذَلِكَ فَقَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏أَلَيْسَ قَدْ صَلَّاهُمَا لَا أَزَالُ ‏ ‏أُصَلِّيهِمَا فَقَالَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏إِنَّكَ لَمُخَالِفٌ لَا تَزَالُ تُحِبُّ الْخِلَافَ مَا بَقِيتَ ‏","","",""],[25433,25433,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ نَافِعٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْنَبَ ابْنَةَ أَبِي سَلَمَةَ ‏ ‏تُحَدِّثُ عَنْ ‏ ‏أُمِّهَا ‏ ‏أَنَّ امْرَأَةً تُوُفِّيَ زَوْجُهَا فَخَافُوا عَلَى عَيْنِهَا فَأَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَأْذَنُوهُ فِي الْكُحْلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏كَانَتْ إِحْدَاكُنَّ تَكُونُ فِي بَيْتِهَا فِي ‏ ‏أَحْلَاسِهَا ‏ ‏أَوْ فِي شَرِّ ‏ ‏أَحْلَاسِهَا ‏ ‏فِي بَيْتِهَا ‏ ‏حَوْلًا ‏ ‏فَإِذَا مَرَّ كَلْبٌ رَمَتْ ‏ ‏بِبَعْرَةٍ ‏ ‏فَخَرَجَتْ فَلَا أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ‏","","",""],[25434,25434,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏تَوْبَةَ الْعَنْبَرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ لَمْ يَكُنْ يَصُومُ مِنْ السَّنَةِ شَهْرًا تَامًّا يُعْلَمُ إِلَّا شَعْبَانَ يَصِلُ بِهِ رَمَضَانَ ‏","","",""],[25435,25435,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَوْ ‏ ‏عَمْرِو بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَرَادَ أَنْ يَنْحَرَ فِي هِلَالِ ذِي الْحِجَّةِ فَلَا يَأْخُذْ مِنْ شَعْرِهِ وَأَظْفَارِهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ مُسْلِمِ بْنِ عَمَّارِ بْنِ أُكَيْمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[25436,25436,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏نَبْهَانَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا وَجَدَ ‏ ‏الْمُكَاتَبُ ‏ ‏مَا يُؤَدِّي فَاحْتَجِبْنَ مِنْهُ ‏","","",""],[25437,25437,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏سَفِينَةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ حُضِرَ جَعَلَ يَقُولُ ‏ ‏الصَّلَاةَ الصَّلَاةَ وَمَا مَلَكَتْ أَيْمَانُكُمْ فَجَعَلَ يَتَكَلَّمُ بِهَا وَمَا يَكَادُ ‏ ‏يَفِيضُ ‏ ‏بِهَا لِسَانُهُ ‏","","",""],[25438,25438,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ رَبِّهِ بْنَ سَعِيدٍ ‏ ‏أَخَا ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏اخْتَلَفَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏فِي الْمُتَوَفَّى عَنْهَا زَوْجُهَا إِذَا وَضَعَتْ حَمْلَهَا ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏تُزَوَّجُ ‏ ‏وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَبْعَدَ ‏ ‏الْأَجَلَيْنِ ‏ ‏قَالَ فَبَعَثُوا إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَقَالَتْ تُوُفِّيَ ‏ ‏زَوْجُ ‏ ‏سُبَيْعَةَ بِنْتِ الْحَارِثِ ‏ ‏فَوَلَدَتْ بَعْدَ وَفَاتِهِ بِخَمْسَ عَشْرَةَ لَيْلَةً فَخَطَبَهَا رَجُلَانِ قَالَ ‏ ‏فَحَطَّتْ ‏ ‏بِنَفْسِهَا إِلَى أَحَدِهِمَا فَلَمَّا خَشُوا أَنْ ‏ ‏تَفْتَاتَ ‏ ‏بِنَفْسِهَا إِلَى أَحَدِهِمَا قَالُوا إِنَّكِ لَمْ تَحِلِّي فَانْطَلَقَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَدْ ‏ ‏حَلَلْتِ ‏ ‏فَانْكِحِي مَنْ شِئْتِ ‏","","",""],[25439,25439,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَقَالَتْ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أَصْحَابِي لَمَنْ لَا يَرَانِي بَعْدَ أَنْ أَمُوتَ أَبَدًا ‏ ‏قَالَ ‏ ‏فَخَرَجَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏مِنْ عِنْدِهَا مَذْعُورًا حَتَّى دَخَلَ عَلَى ‏ ‏عُمَرَ ‏ ‏فَقَالَ لَهُ اسْمَعْ مَا تَقُولُ أُمُّكَ فَقَامَ ‏ ‏عُمَرُ ‏ ‏حَتَّى أَتَاهَا فَدَخَلَ عَلَيْهَا فَسَأَلَهَا ثُمَّ قَالَ ‏ ‏أَنْشُدُكِ ‏ ‏بِاللَّهِ أَمِنْهُمْ أَنَا فَقَالَتْ لَا وَلَنْ ‏ ‏أُبَرِّئَ ‏ ‏بَعْدَكَ أَحَدًا ‏","","",""],[25440,25440,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو عُبَيْدَةَ بْنُ عَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏أَنَّ ‏ ‏أُمَّهُ ‏ ‏زَيْنَبَ ابْنَةَ أَبِي سَلَمَةَ ‏ ‏أَخْبَرَتْهُ أَنَّ ‏ ‏أُمَّهَا ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ تَقُولُ أَبَى سَائِرُ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُدْخِلْنَ عَلَيْهِنَّ أَحَدًا بِتِلْكَ الرَّضَاعَةِ وَقُلْنَ ‏ ‏لِعَائِشَةَ ‏ ‏وَاللَّهِ ‏ ‏مَا ‏ ‏نُرَى هَذَا إِلَّا رُخْصَةً أَرْخَصَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِسَالِمٍ ‏ ‏خَاصَّةً فَمَا هُوَ بِدَاخِلٍ عَلَيْنَا أَحَدٌ بِهَذِهِ الرَّضَاعَةِ وَلَا رَائِينَا ‏","","",""],[25441,25441,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا عِيَاضٍ ‏ ‏حَدَّثَ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ ‏ ‏بَعَثَ إِلَى ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْسَلَ إِلَيْهَا مَوْلَاهَا فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا فَيَصُومُ وَلَا يُفْطِرُ قَالَ فَرَجَعَ إِلَيْهِ فَأَخْبَرَهُ قَالَ فَبَعَثَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَبَعَثَ إِلَيْهَا مَوْلَاهَا ‏ ‏أَوْ غُلَامَهَا ‏ ‏ذَكْوَانَ ‏ ‏فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ جِمَاعٍ غَيْرِ ‏ ‏حُلُمٍ ‏ ‏فَيَصُومُ وَلَا يُفْطِرُ فَقَالَ لَهُ ائْتِ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَأَخْبِرْهُ فَانْطَلَقَ إِلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَأَخْبَرَهُ عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَنْ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَ هُمَا أَعْلَمُ ‏","","",""],[25442,25442,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ ‏ ‏عَنْ ‏ ‏أَبِي عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ بْنَ الْحَكَمِ ‏ ‏بَعَثَهُ إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَائِشَةَ ‏ ‏قَالَ فَلَقِيتُ غُلَامَهَا ‏ ‏نَافِعًا ‏ ‏فَأَرْسَلْتُهُ إِلَيْهَا فَسَأَلَهَا قَالَ فَرَجَعَ إِلَيَّ فَأَخْبَرَنِي أَنَّهَا قَالَتْ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا وَيُصْبِحُ صَائِمًا قَالَ ثُمَّ بَعَثَنِي إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَلَقِيتُ غُلَامَهَا ‏ ‏ذَكْوَانَ ‏ ‏فَأَرْسَلْتُهُ إِلَيْهَا فَرَجَعَ إِلَيَّ فَأَخْبَرَنِي أَنَّهَا قَالَتْ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُصْبِحُ جُنُبًا مِنْ جِمَاعٍ غَيْرِ احْتِلَامٍ ثُمَّ يُصْبِحُ صَائِمًا قَالَ فَأَتَيْتُ ‏ ‏مَرْوَانَ ‏ ‏فَأَخْبَرْتُهُ فَقَالَ أَقْسَمْتُ عَلَيْكَ لَتَأْتِيَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَلَتُخْبِرَنَّهُ بِهِ فَأَتَيْتُهُ فَأَخْبَرْتُهُ فَقَالَ هُنَّ أَعْلَمُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ ‏ ‏عَنْ ‏ ‏أَبِي عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ بْنَ الْحَكَمِ ‏ ‏بَعَثَهُ إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَائِشَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ ثُمَّ لَقِيَ غُلَامَ ‏ ‏عَائِشَةَ ‏ ‏ذَكْوَانَ أَبَا عَمْرٍو ‏ ‏وَقَالَ لَقِيتُ ‏ ‏نَافِعًا ‏ ‏غُلَامَ ‏ ‏أُمِّ سَلَمَةَ ‏","","",""],[25443,25443,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُدْرِكُهُ الْفَجْرُ وَهُوَ جُنُبٌ مِنْ أَهْلِهِ ثُمَّ يَغْتَسِلُ وَيَصُومُ ‏","","",""],[25444,25444,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا فِي رَمَضَانَ مِنْ أَهْلِهِ ثُمَّ يَغْتَسِلُ وَيَصُومُ ‏","","",""],[25445,25445,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَصْبَحَ جُنُبًا مِنْ غَيْرِ احْتِلَامٍ فَلَا يَصُومُ ‏ ‏فَانْطَلَقَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَأَبُوهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَتَّى دَخَلَا عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَائِشَةَ ‏ ‏فَكِلْتَاهُمَا قَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ غَيْرِ احْتِلَامٍ ثُمَّ يَصُومُ فَانْطَلَقَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَأَبُوهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَأَتَيَا ‏ ‏مَرْوَانَ ‏ ‏فَحَدَّثَاهُ ثُمَّ قَالَ عَزَمْتُ عَلَيْكُمَا لَمَا انْطَلَقْتُمَا إِلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَحَدَّثْتُمَاهُ فَانْطَلَقَا إِلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَأَخْبَرَاهُ قَالَ قَالَتَاهُ لَكُمَا فَقَالَا نَعَمْ قَالَ هُمَا أَعْلَمُ إِنَّمَا أَنَبَأَنِيهِ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏","","",""],[25446,25446,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا ثُمَّ يَصُومُ يَوْمَهُ ‏","","",""],[25447,25447,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَصْبَحَ جُنُبًا فَلَا يَصُومُ ‏ ‏فَانْطَلَقَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَأَبُوهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَتَّى دَخَلَا عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَائِشَةَ ‏ ‏فَكِلْتَاهُمَا قَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ غَيْرِ احْتِلَامٍ ثُمَّ يَصُومُ فَانْطَلَقَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَأَبُوهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَأَتَيَا ‏ ‏مَرْوَانَ ‏ ‏فَحَدَّثَاهُ ثُمَّ قَالَ عَزَمْتُ عَلَيْكُمَا لَمَا انْطَلَقْتُمَا إِلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَحَدَّثْتُمَاهُ فَانْطَلَقَا إِلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَأَخْبَرَاهُ قَالَ هُمَا قَالَتَاهُ لَكُمَا فَقَالَا نَعَمْ قَالَ هُمَا أَعْلَمُ إِنَّمَا أَنَبَأَنِيهِ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏","","",""],[25448,25448,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏بِمِنًى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَصَابَ أَحَدَكُمْ مُصِيبَةٌ فَلْيَقُلْ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ عِنْدَكَ ‏ ‏احْتَسَبْتُ ‏ ‏مُصِيبَتِي وَأْجُرْنِي فِيهَا وَأَبْدِلْنِي مَا هُوَ خَيْرٌ مِنْهَا فَلَمَّا ‏ ‏احْتُضِرَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏قَالَ اللَّهُمَّ اخْلُفْنِي فِي أَهْلِي بِخَيْرٍ فَلَمَّا قُبِضَ قُلْتُ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ عِنْدَكَ ‏ ‏أَحْتَسِبُ ‏ ‏مُصِيبَتِي فَأْجُرْنِي فِيهَا قَالَتْ وَأَرَدْتُ أَنْ أَقُولَ وَأَبْدِلْنِي خَيْرًا مِنْهَا فَقُلْتُ وَمَنْ خَيْرٌ مِنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏فَمَا زِلْتُ حَتَّى قُلْتُهَا فَلَمَّا ‏ ‏انْقَضَتْ ‏ ‏عِدَّتُهَا خَطَبَهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَرَدَّتْهُ ثُمَّ خَطَبَهَا ‏ ‏عُمَرُ ‏ ‏فَرَدَّتْهُ فَبَعَثَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ مَرْحَبًا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِرَسُولِهِ أَخْبِرْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي امْرَأَةٌ غَيْرَى وَأَنِّي مُصْبِيَةٌ وَأَنَّهُ لَيْسَ أَحَدٌ مِنْ أَوْلِيَائِي شَاهِدًا فَبَعَثَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا قَوْلُكِ إِنِّي مُصْبِيَةٌ فَإِنَّ اللَّهَ ‏ ‏سَيَكْفِيكِ صِبْيَانَكِ وَأَمَّا قَوْلُكِ إِنِّي غَيْرَى ‏ ‏فَسَأَدْعُو اللَّهَ أَنْ يُذْهِبَ غَيْرَتَكِ وَأَمَّا ‏ ‏الْأَوْلِيَاءُ ‏ ‏فَلَيْسَ أَحَدٌ مِنْهُمْ شَاهِدٌ ‏ ‏وَلَا غَائِبٌ إِلَّا ‏ ‏سَيَرْضَانِي قُلْتُ يَا ‏ ‏عُمَرُ ‏ ‏قُمْ فَزَوِّجْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنِّي لَا أَنْقُصُكِ شَيْئًا مِمَّا أَعْطَيْتُ أُخْتَكِ فُلَانَةَ ‏ ‏رَحَيَيْنِ ‏ ‏وَجَرَّتَيْنِ ‏ ‏وَوِسَادَةً مِنْ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهَا لِيفٌ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِيهَا فَإِذَا جَاءَ أَخَذَتْ ‏ ‏زَيْنَبَ ‏ ‏فَوَضَعَتْهَا فِي حِجْرِهَا لِتُرْضِعَهَا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيِيًّا كَرِيمًا ‏ ‏يَسْتَحْيِي فَرَجَعَ فَفَعَلَ ذَلِكَ مِرَارًا ‏ ‏فَفَطِنَ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏لِمَا تَصْنَعُ فَأَقْبَلَ ذَاتَ يَوْمٍ وَجَاءَ ‏ ‏عَمَّارٌ ‏ ‏وَكَانَ أَخَاهَا لِأُمِّهَا فَدَخَلَ عَلَيْهَا ‏ ‏فَانْتَشَطَهَا ‏ ‏مِنْ حِجْرِهَا وَقَالَ دَعِي هَذِهِ الْمَقْبُوحَةَ ‏ ‏الْمَشْقُوحَةَ ‏ ‏الَّتِي آذَيْتِ بِهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ فَجَعَلَ يُقَلِّبُ بَصَرَهُ فِي الْبَيْتِ وَيَقُولُ أَيْنَ ‏ ‏زَنَابُ ‏ ‏مَا فَعَلَتْ ‏ ‏زَنَابُ ‏ ‏قَالَتْ جَاءَ ‏ ‏عَمَّارٌ ‏ ‏فَذَهَبَ بِهَا قَالَ ‏ ‏فَبَنَى ‏ ‏بِأَهْلِهِ ثُمَّ قَالَ إِنْ شِئْتِ أَنْ أُسَبِّعَ لَكِ ‏ ‏سَبَّعْتُ ‏ ‏لِلنِّسَاءِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏وَقَالَ ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏ابْنُ عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏مُرْسَلٌ ‏","","",""],[25449,25449,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ هَلْ لِي مِنْ أَجْرٍ فِي ‏ ‏بَنِي أَبِي سَلَمَةَ ‏ ‏أَنْ أُنْفِقَ عَلَيْهِمْ وَلَسْتُ بِتَارِكَتِهِمْ هَكَذَا وَهَكَذَا إِنَّمَا هُمْ بَنِيَّ قَالَ ‏ ‏نَعَمْ لَكِ فِيهِمْ ‏ ‏أَجْرٌ ‏ ‏مَا أَنْفَقْتِ عَلَيْهِمْ ‏","","",""],[25450,25450,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رِبْعِيُّ بْنُ حِرَاشٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏سَاهِمُ ‏ ‏الْوَجْهِ قَالَتْ فَحَسِبْتُ ذَلِكَ مِنْ وَجَعٍ فَقُلْتُ يَا رَسُولَ اللَّهِ أَرَاكَ سَاهِمَ الْوَجْهِ أَفَمِنْ وَجَعٍ فَقَالَ ‏ ‏لَا وَلَكِنَّ الدَّنَانِيرَ السَّبْعَةَ الَّتِي أُتِينَا بِهَا أَمْسِ أَمْسَيْنَا وَلَمْ نُنْفِقْهَا نَسِيتُهَا فِي خُصْمِ الْفِرَاشِ ‏","","",""],[25451,25451,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَمَّارٍ الدُّهْنِيِّ ‏ ‏عَنْ ‏ ‏امْرَأَةٍ ‏ ‏مِنْهُمْ ‏ ‏أَنَّهَا ‏ ‏سَأَلَتْ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏النَّبِيذِ ‏ ‏فَقَالَتْ كُلُّ مُسْكِرٍ حَرَامٌ ‏ ‏وَنَهَى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُزَفَّتِ ‏ ‏وَعَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏","","",""],[25452,25452,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ وَاصِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْقَاسِمُ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجُّ جِهَادُ كُلِّ ضَعِيفٍ ‏","","",""],[25453,25453,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ اجْتَمَعَ هُوَ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏عِنْدَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَبَعَثُوا ‏ ‏كُرَيْبًا ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏يَسْأَلُهَا فَذَكَرَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏سُبَيْعَةَ الْأَسْلَمِيَّةَ ‏ ‏تُوُفِّيَ عَنْهَا ‏ ‏زَوْجُهَا ‏ ‏فَنُفِسَتْ ‏ ‏بَعْدَهُ بِلَيَالٍ فَذَكَرَتْ ‏ ‏سُبَيْعَةُ ‏ ‏ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهَا أَنْ تَتَزَوَّجَ ‏","","",""],[25454,25454,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَ حَدَّثَتْنَا ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا حَضَرَتْ الصَّلَاةُ وَحَضَرَ الْعَشَاءُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[25455,25455,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي امْرَأَةٌ أَشُدُّ ‏ ‏ضَفْرَ ‏ ‏رَأْسِي ‏ ‏أَفَأَنْقُضُهُ ‏ ‏عِنْدَ الْغُسْلِ مِنْ الْجَنَابَةِ فَقَالَ ‏ ‏إِنَّمَا ‏ ‏يَكْفِيكِ ثَلَاثُ ‏ ‏حَفَنَاتٍ ‏ ‏تَصُبِّينَهَا عَلَى رَأْسِكِ ‏","","",""],[25456,25456,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْأَزْرَقِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ ثُمَّ دَخَلَ بَيْتِي فَصَلَّى رَكْعَتَيْنِ فَقُلْتُ يَا رَسُولَ اللَّهِ صَلَّيْتَ صَلَاةً لَمْ تَكُنْ تُصَلِّيهَا فَقَالَ ‏ ‏قَدِمَ عَلَيَّ مَالٌ فَشَغَلَنِي عَنْ الرَّكْعَتَيْنِ كُنْتُ أَرْكَعُهُمَا بَعْدَ الظُّهْرِ فَصَلَّيْتُهُمَا الْآنَ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَفَنَقْضِيهِمَا إِذَا فَاتَتَا قَالَ لَا ‏","","",""],[25457,25457,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو كَعْبٍ ‏ ‏صَاحِبُ الْحَرِيرِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏يَا أُمَّ الْمُؤْمِنِينَ مَا كَانَ أَكْثَرَ دُعَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ عِنْدَكِ قَالَتْ كَانَ أَكْثَرُ دُعَائِهِ يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ قَالَتْ فَقُلْتُ لَهُ يَا رَسُولَ اللَّهِ مَا ‏ ‏أَكْثَرَ دُعَاءَكَ يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ قَالَ يَا ‏ ‏أُمَّ سَلَمَةَ ‏ ‏مَا مِنْ آدَمِيٍّ إِلَّا وَقَلْبُهُ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ عَزَّ وَجَلَّ مَا شَاءَ أَقَامَ وَمَا شَاءَ ‏ ‏أَزَاغَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏سَأَلْتُ أَبِي عَنْ ‏ ‏أَبِي كَعْبٍ ‏ ‏فَقَالَ ثِقَةٌ وَاسْمُهُ ‏ ‏عَبْدُ رَبِّهِ بْنُ عُبَيْدٍ ‏","","",""],[25458,25458,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏مَا نَسِيتُهُ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏وَقَدْ ‏ ‏اغْبَرَّ ‏ ‏صَدْرُهُ وَهُوَ ‏ ‏يُعَاطِيهِمُ اللَّبَنَ وَيَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْخَيْرَ خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏قَالَ فَأَقْبَلَ ‏ ‏عَمَّارٌ ‏ ‏فَلَمَّا رَآهُ قَالَ وَيْحَكَ ‏ ‏ابْنَ سُمَيَّةَ ‏ ‏تَقْتُلُكَ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏ ‏قَالَ ‏ ‏فَحَدَّثْتُهُ ‏ ‏مُحَمَّدًا ‏ ‏فَقَالَ عَنْ ‏ ‏أُمِّهِ ‏ ‏أَمَا إِنَّهَا قَدْ كَانَتْ ‏ ‏تَلِجُ ‏ ‏عَلَى أَمِّ الْمُؤْمِنِينَ ‏","","",""],[25459,25459,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ بِالنِّسَاءِ قَالَ ‏ ‏يُرْخِينَ شِبْرًا قُلْتُ إِذَنْ يَنْكَشِفَ عَنْهُنَّ يَا رَسُولَ اللَّهِ قَالَ فَذِرَاعٌ لَا يَزِدْنَ عَلَيْهِ ‏","","",""],[25460,25460,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏جَعَلَتْ ‏ ‏شَعَائِرَ ‏ ‏مِنْ ذَهَبٍ فِي رَقَبَتِهَا فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْرَضَ عَنْهَا فَقُلْتُ أَلَا تَنْظُرُ إِلَى زِينَتِهَا فَقَالَ عَنْ زِينَتِكِ أُعْرِضُ قَالَ زَعَمُوا أَنَّهُ قَالَ ‏ ‏مَا ضَرَّ إِحْدَاكُنَّ لَوْ جَعَلَتْ ‏ ‏خُرْصًا ‏ ‏مِنْ ‏ ‏وَرِقٍ ‏ ‏ثُمَّ جَعَلَتْهُ بِزَعْفَرَانٍ ‏","","",""],[25461,25461,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ صَيْفِيٍّ ‏ ‏أَنَّ ‏ ‏عِكْرِمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏أَخْبَرْتُهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَفَ أَنْ لَا يَدْخُلَ عَلَى بَعْضِ أَهْلِهِ شَهْرًا فَلَمَّا مَضَى تِسْعَةٌ وَعِشْرُونَ يَوْمًا غَدَا عَلَيْهِمْ أَوْ رَاحَ فَقِيلَ لَهُ حَلَفْتَ يَا نَبِيَّ اللَّهِ لَا تَدْخُلُ عَلَيْهِمْ شَهْرًا فَقَالَ إِنَّ الشَّهْرَ تِسْعَةٌ وَعِشْرُونَ يَوْمًا ‏","","",""],[25462,25462,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَ ‏ ‏سَفِينَةُ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ عَامَّةُ وَصِيَّةِ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ مَوْتِهِ ‏ ‏الصَّلَاةَ الصَّلَاةَ وَمَا مَلَكَتْ أَيْمَانُكُمْ حَتَّى جَعَلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَجْلِجُهَا ‏ ‏فِي صَدْرِهِ وَمَا ‏ ‏يَفِيضُ ‏ ‏بِهَا لِسَانُهُ ‏","","",""],[25463,25463,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏رَبِّ ‏ ‏اغْفِرْ وَارْحَمْ وَاهْدِنِي السَّبِيلَ الْأَقْوَمَ ‏","","",""],[25464,25464,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُمَارَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أُمُّ وَلَدٍ لِابْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَتْ ‏ ‏كُنْتُ امْرَأَةً لِي ذَيْلٌ طَوِيلٌ وَكُنْتُ آتِي الْمَسْجِدَ وَكُنْتُ أَسْحَبُهُ فَسَأَلْتُ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏قُلْتُ إِنِّي امْرَأَةٌ ‏ ‏ذَيْلِي ‏ ‏طَوِيلٌ وَإِنِّي آتِي الْمَسْجِدَ وَإِنِّي أَسْحَبُهُ عَلَى الْمَكَانِ الْقَذِرِ ثُمَّ أَسْحَبُهُ عَلَى الْمَكَانِ ‏ ‏الطَّيِّبِ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا مَرَّتْ عَلَى الْمَكَانِ الْقَذِرِ ثُمَّ مَرَّتْ عَلَى الْمَكَانِ ‏ ‏الطَّيِّبِ ‏ ‏فَإِنَّ ذَلِكَ طَهُورٌ ‏","","",""],[25465,25465,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ بْنُ صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ شِهَابٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ وَهْبِ بْنِ زَمْعَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَرَجَ تَاجِرًا إِلَى ‏ ‏بُصْرَى ‏ ‏وَمَعَهُ ‏ ‏نُعَيْمَانُ ‏ ‏وَسُوَيْبِطُ بْنُ حَرْمَلَةَ ‏ ‏وَكِلَاهُمَا ‏ ‏بَدْرِيٌّ ‏ ‏وَكَانَ ‏ ‏سُوَيْبِطٌ ‏ ‏عَلَى ‏ ‏الزَّادِ ‏ ‏فَجَاءَهُ ‏ ‏نُعَيْمَانُ ‏ ‏فَقَالَ أَطْعِمْنِي فَقَالَ لَا حَتَّى يَأْتِيَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَكَانَ ‏ ‏نُعَيْمَانُ ‏ ‏رَجُلًا ‏ ‏مِضْحَاكًا ‏ ‏مَزَّاحًا فَقَالَ لَأَغِيظَنَّكَ فَذَهَبَ إِلَى أُنَاسٍ جَلَبُوا ظَهْرًا فَقَالَ ابْتَاعُوا مِنِّي غُلَامًا عَرَبِيًّا فَارِهًا وَهُوَ ذُو لِسَانٍ وَلَعَلَّهُ يَقُولُ أَنَا حُرٌّ فَإِنْ كُنْتُمْ تَارِكِيهِ لِذَلِكَ فَدَعُونِي لَا تُفْسِدُوا عَلَيَّ غُلَامِي فَقَالُوا بَلْ نَبْتَاعُهُ مِنْكَ بِعَشْرِ ‏ ‏قَلَائِصَ ‏ ‏فَأَقْبَلَ بِهَا يَسُوقُهَا وَأَقْبَلَ بِالْقَوْمِ حَتَّى ‏ ‏عَقَلَهَا ‏ ‏ثُمَّ قَالَ لِلْقَوْمِ دُونَكُمْ هُوَ هَذَا فَجَاءَ الْقَوْمُ فَقَالُوا قَدْ اشْتَرَيْنَاكَ قَالَ ‏ ‏سُوَيْبِطٌ ‏ ‏هُوَ كَاذِبٌ أَنَا رَجُلٌ حُرٌّ فَقَالُوا قَدْ أَخْبَرَنَا خَبَرَكَ وَطَرَحُوا الْحَبْلَ فِي رَقَبَتِهِ فَذَهَبُوا بِهِ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَأُخْبِرَ ‏ ‏فَذَهَبَ هُوَ وَأَصْحَابٌ لَهُ فَرَدُّوا ‏ ‏الْقَلَائِصَ ‏ ‏وَأَخْذُوهُ فَضَحِكَ مِنْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ ‏ ‏حَوْلًا ‏","","",""],[25466,25466,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏هِنْدُ ابْنَةُ الْحَارِثِ الْقُرَشِيَّةُ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهَا ‏ ‏أَنَّ النِّسَاءَ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ مِنْ الصَّلَاةِ الْمَكْتُوبَةِ ‏ ‏قُمْنَ ‏ ‏وَثَبَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَثَبَتَ مَنْ صَلَّى مِنْ الرِّجَالِ مَا شَاءَ اللَّهُ فَإِذَا قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ الرِّجَالُ ‏","","",""],[25467,25467,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَرَمِيٌّ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏صَاحِبٍ ‏ ‏لَهُ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَكُونُ اخْتِلَافٌ عِنْدَ مَوْتِ خَلِيفَةٍ فَيَخْرُجُ رَجُلٌ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏هَارِبٌ إِلَى ‏ ‏مَكَّةَ ‏ ‏فَيَأْتِيهِ نَاسٌ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فَيُخْرِجُونَهُ وَهُوَ كَارِهٌ فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ ‏ ‏وَالْمَقَامِ ‏ ‏فَيُبْعَثُ إِلَيْهِمْ جَيْشٌ مِنْ ‏ ‏الشَّامِ ‏ ‏فَيُخْسَفُ بِهِمْ ‏ ‏بِالْبَيْدَاءِ ‏ ‏فَإِذَا رَأَى النَّاسُ ذَلِكَ أَتَتْهُ أَبْدَالُ ‏ ‏الشَّامِ ‏ ‏وَعَصَائِبُ ‏ ‏الْعِرَاقِ ‏ ‏فَيُبَايِعُونَهُ ثُمَّ يَنْشَأُ رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَخْوَالُهُ كَلْبٌ فَيَبْعَثُ إِلَيْهِ الْمَكِّيُّ بَعْثًا فَيَظْهَرُونَ عَلَيْهِمْ وَذَلِكَ بَعْثُ كَلْبٍ وَالْخَيْبَةُ لِمَنْ لَمْ يَشْهَدْ ‏ ‏غَنِيمَةَ ‏ ‏كَلْبٍ فَيَقْسِمُ الْمَالَ وَيُعْمِلُ فِي النَّاسِ سُنَّةَ نَبِيِّهِمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيُلْقِي الْإِسْلَامُ ‏ ‏بِجِرَانِهِ ‏ ‏إِلَى الْأَرْضِ يَمْكُثُ تِسْعَ سِنِينَ ‏ ‏قَالَ ‏ ‏حَرَمِيٌّ ‏ ‏أَوْ سَبْعَ ‏","","",""],[25468,25468,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَيْقَظَ مِنْ مَنَامِهِ وَهُوَ يَسْتَرْجِعُ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ مَا شَأْنُكَ قَالَ ‏ ‏طَائِفَةٌ مِنْ أُمَّتِي يُخْسَفُ بِهِمْ ثُمَّ يُبْعَثُونَ إِلَى رَجُلٍ فَيَأْتِي ‏ ‏مَكَّةَ ‏ ‏فَيَمْنَعُهُ اللَّهُ مِنْهُمْ وَيُخْسَفُ بِهِمْ مَصْرَعُهُمْ وَاحِدٌ ‏ ‏وَمَصَادِرُهُمْ شَتَّى قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ يَكُونُ مَصْرَعُهُمْ وَاحِدًا وَمَصَادِرُهُمْ شَتَّى قَالَ إِنَّ مِنْهُمْ مَنْ يُكْرَهُ فَيَجِيءُ مُكْرَهًا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[25469,25469,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏مَوْلَى ‏ ‏عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ قَالَتْ لَا قُلْتُ فَإِنَّ ‏ ‏عَائِشَةَ ‏ ‏تُخْبِرُ النَّاسَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ قَالَتْ قُلْتُ لَعَلَّهُ أَنْ كَانَ لَا يَتَمَالَكُ عَنْهَا حُبًّا أَمَّا أَنَا فَلَا ‏","","",""],[25470,25470,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏وَابْنُ لَهِيعَةَ ‏ ‏قَالَا سَمِعْنَا ‏ ‏يَزِيدَ بْنَ أَبِي حَبِيبٍ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبُو عِمْرَانَ ‏ ‏قَالَ قَالَتْ ‏ ‏لِي ‏ ‏أُمُّ سَلَمَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَا آلَ ‏ ‏مُحَمَّدٍ ‏ ‏مَنْ حَجَّ مِنْكُمْ ‏ ‏فَلْيُهِلَّ ‏ ‏فِي حَجِّهِ ‏ ‏أَوْ فِي حَجَّتِهِ شَكَّ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏","","",""],[25471,25471,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَقَالَ يَا أُمَّ الْمُؤْمِنِينَ إِنِّي أَخْشَى أَنْ أَكُونَ قَدْ هَلَكْتُ إِنِّي مِنْ أَكْثَرِ ‏ ‏قُرَيْشٍ ‏ ‏مَالًا بِعْتُ أَرْضًا لِي بِأَرْبَعِينَ أَلْفَ دِينَارٍ فَقَالَتْ أَنْفِقْ يَا بُنَيَّ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أَصْحَابِي مَنْ لَا يَرَانِي بَعْدَ أَنْ أُفَارِقَهُ ‏ ‏فَأَتَيْتُ ‏ ‏عُمَرَ ‏ ‏فَأَخْبَرْتُهُ فَأَتَاهَا فَقَالَ بِاللَّهِ أَنَا مِنْهُمْ قَالَتْ اللَّهُمَّ لَا وَلَنْ أُبَرِّئَ أَحَدًا بَعْدَكَ ‏","","",""],[25472,25472,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو تُمَيْلَةَ يَحْيَى بْنُ وَاضِحٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْمُؤْمِنِ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏لَمْ يَكُنْ ثَوْبٌ أَحَبَّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ قَمِيصٍ ‏","","",""],[25473,25473,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَوْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏كَيْفَ نَسْأَلُ أَحَدًا وَفِينَا أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَعَثَ إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَأَخْبَرَتْهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الصَّلَاةِ ‏ ‏فَنَشَلَتْ ‏ ‏لَهُ كَتِفًا مِنْ قِدْرٍ فَأَكَلَهَا ثُمَّ خَرَجَ فَصَلَّى ‏","","",""],[25474,25474,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏بِمِنًى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَصَابَتْهُ مُصِيبَةٌ فَلْيَقُلْ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ عِنْدَكَ ‏ ‏أَحْتَسِبُ ‏ ‏مُصِيبَتِي فَأْجُرْنِي فِيهَا وَأَبْدِلْنِي بِهَا خَيْرًا مِنْهَا فَلَمَّا مَاتَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏قُلْتُهَا فَجَعَلْتُ كُلَّمَا بَلَغْتُ وَأَبْدِلْنِي بِهَا خَيْرًا مِنْهَا قُلْتُ فِي نَفْسِي وَمَنْ خَيْرٌ مِنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏ثُمَّ قُلْتُهَا فَلَمَّا انْقَضَتْ عِدَّتُهَا بَعَثَ إِلَيْهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏يَخْطُبُهَا فَلَمْ تَزَوَّجْهُ فَبَعَثَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏يَخْطُبُهَا عَلَيْهِ فَقَالَتْ أَخْبِرْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي امْرَأَةٌ غَيْرَى وَأَنِّي امْرَأَةٌ مُصْبِيَةٌ وَلَيْسَ أَحَدٌ مِنْ أَوْلِيَائِي شَاهِدًا فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ لَهُ ذَلِكَ فَقَالَ ارْجِعْ إِلَيْهَا فَقُلْ لَهَا أَمَّا قَوْلُكِ إِنِّي امْرَأَةٌ غَيْرَى ‏ ‏فَأَدْعُو اللَّهَ عَزَّ وَجَلَّ فَيُذْهِبُ غَيْرَتَكِ وَأَمَّا قَوْلُكِ إِنِّي امْرَأَةٌ مُصْبِيَةٌ فَسَتُكْفَيْنَ صِبْيَانَكِ وَأَمَّا قَوْلُكِ إِنَّهُ لَيْسَ أَحَدٌ مِنْ أَوْلِيَائِكِ شَاهِدًا فَلَيْسَ أَحَدٌ مِنْ أَوْلِيَائِكِ ‏ ‏شَاهِدٌ وَلَا غَائِبٌ يَكْرَهُ ذَلِكَ ‏","","",""],[25475,25475,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا قَدِمَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏الْمَدِينَةَ ‏ ‏عَلَى ‏ ‏الْأَنْصَارِ ‏ ‏تَزَوَّجُوا مِنْ نِسَائِهِمْ وَكَانَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏يُجَبُّونَ ‏ ‏وَكَانَتْ ‏ ‏الْأَنْصَارُ ‏ ‏لَا ‏ ‏تُجَبِّي ‏ ‏فَأَرَادَ رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏امْرَأَتَهُ عَلَى ذَلِكَ ‏ ‏فَأَبَتْ ‏ ‏عَلَيْهِ حَتَّى تَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَأَتَتْهُ ‏ ‏فَاسْتَحْيَتْ أَنْ تَسْأَلَهُ فَسَأَلَتْهُ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَنَزَلَتْ ‏ { ‏نِسَاؤُكُمْ ‏ ‏حَرْثٌ ‏ ‏لَكُمْ فَأْتُوا ‏ ‏حَرْثَكُمْ ‏ ‏أَنَّى شِئْتُمْ ‏} ‏وَقَالَ لَا إِلَّا فِي صِمَامٍ وَاحِدٍ ‏ ‏و قَالَ ‏ ‏وَكِيعٌ ‏ ‏ابْنُ سَابِطٍ ‏ ‏رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏","","",""],[25476,25476,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهَا ‏ ‏قَالَتْ ‏ ‏قَالَ ‏ ‏مُخَنَّثٌ ‏ ‏لَأَخِيهَا ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أُمَيَّةَ ‏ ‏إِنْ فَتَحَ اللَّهُ عَلَيْكُمْ ‏ ‏الطَّائِفَ ‏ ‏غَدًا دَلَلْتُكَ عَلَى ‏ ‏بِنْتِ غَيْلَانَ ‏ ‏فَإِنَّهَا تُقْبِلُ بِأَرْبَعٍ ‏ ‏وَتُدْبِرُ ‏ ‏بِثَمَانٍ فَسَمِعَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَخْرِجُوا هَؤُلَاءِ مِنْ بُيُوتِكُمْ فَلَا يَدْخُلُوا عَلَيْكُمْ ‏","","",""],[25477,25477,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏مَوْلًى ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تُحَدِّثُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي ‏ ‏دُبُرِ ‏ ‏الْفَجْرِ إِذَا صَلَّى ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَعَمَلًا مُتَقَبَّلًا وَرِزْقًا طَيِّبًا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏مَوْلًى ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِذَا صَلَّى الصُّبْحَ حِينَ يُسَلِّمُ فَذَكَرَهُ ‏","","",""],[25478,25478,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ الْبَاهِلِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُهَاجِرًا الْمَكِّيَّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْزُو جَيْشٌ ‏ ‏البَيْتَ ‏ ‏حَتَّى إِذَا كَانُوا ‏ ‏بِبَيْدَاءَ ‏ ‏مِنْ الْأَرْضِ خُسِفَ بِهِمْ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ الْمُكْرَهَ مِنْهُمْ قَالَ يُبْعَثُ عَلَى ‏ ‏نِيَّتِهِ ‏","","",""],[25479,25479,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏بَيْنَا أَنَا ‏ ‏مُضْطَجِعَةٌ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْخَمِيلَةِ ‏ ‏إِذْ حِضْتُ ‏ ‏فَانْسَلَلْتُ ‏ ‏فَأَخَذْتُ ثِيَابَ حَيْضَتِي فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنُفِسْتِ قُلْتُ نَعَمْ ‏ ‏فَدَعَانِي ‏ ‏فَاضْطَجَعْتُ ‏ ‏مَعَهُ فِي ‏ ‏الْخَمِيلَةِ ‏ ‏وَكَانَتْ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلَانِ مِنْ الْإِنَاءِ الْوَاحِدِ مِنْ الْجَنَابَةِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُهَا وَهُوَ صَائِمٌ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَاه ‏ ‏هُدْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏بِإِسْنَادِ هَذَا الْحَدِيثِ وَمَعْنَاهُ ‏","","",""],[25480,25480,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا خَرَجَ مِنْ بَيْتِهِ قَالَ ‏ ‏بِاسْمِكَ رَبِّي إِنِّي أَعُوذُ بِكَ أَنْ أَزِلَّ أَوْ أَضِلَّ أَوْ أَظْلِمَ أَوْ أُظْلَمَ أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ ‏","","",""],[25481,25481,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمَّارٍ الدُّهْنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَوَائِمُ الْمِنْبَرِ رَوَاتِبُ فِي الْجَنَّةِ ‏","","",""],[25482,25482,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏ابْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏نِسَاؤُكُمْ ‏ ‏حَرْثٌ ‏ ‏لَكُمْ فَأْتُوا ‏ ‏حَرْثَكُمْ ‏ ‏أَنَّى شِئْتُمْ ‏} ‏قَالَ صِمَامًا وَاحِدًا ‏","","",""],[25483,25483,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏لَيْثِ بْنِ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَبَّلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ صَائِمٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏فَذَكَرَ مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[25484,25484,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏مَا مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى كَانَ ‏ ‏أَكْثَرَ صَلَاتِهِ قَاعِدًا إِلَّا الْمَكْتُوبَةَ وَكَانَ أَحَبُّ الْعَمَلِ إِلَيْهِ مَا دَاوَمَ الْعَبْدُ عَلَيْهِ وَإِنْ كَانَ يَسِيرًا ‏","","",""],[25485,25485,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَوْنٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَدَّادٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ الْوُضُوءُ مِمَّا مَسَّتْ النَّارُ فَذَكَرْتُ ذَلِكَ ‏ ‏أَوْ ذَكَرَ ذَلِكَ ‏ ‏لِمَرْوَانَ ‏ ‏فَقَالَ مَا أَدْرِي مَنْ نَسْأَلُ كَيْفَ وَفِينَا أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَعَثَنِي إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَحَدَّثَتْنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الصَّلَاةِ فَتَنَاوَلَ ‏ ‏عَرْقًا ‏ ‏فَانْتَهَسَ ‏ ‏عَظْمًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[25486,25486,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُمْهَانَ ‏ ‏عَنْ ‏ ‏سَفِينَةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَعْتَقَتْنِي ‏ ‏أُمُّ سَلَمَةَ ‏ ‏وَاشْتَرَطَتْ عَلَيَّ أَنْ أَخْدُمَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا عَاشَ ‏","","",""],[25487,25487,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي مُعَاوِيَةَ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ تَغْتَسِلُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[25488,25488,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ أَبِي مُطِيعٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَأَخْرَجَتْ إِلَيْنَا شَعْرًا مِنْ شَعْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَخْضُوبًا ‏ ‏بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏","","",""],[25489,25489,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا قَدِمَتْ وَهِيَ مَرِيضَةٌ فَذَكَرَتْ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ قَالَتْ فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏يَقْرَأُ ‏ ‏بِالطُّورِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَرَأْتُهُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏قَالَتْ ‏ ‏فَطُفْتُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَئِذٍ ‏ ‏يُصَلِّي بِجَنْبِ ‏ ‏الْبَيْتِ ‏ ‏وَهُوَ يَقْرَأُ ‏ ‏بِالطُّورِ وَكِتَابٍ مَسْطُورٍ ‏","","",""],[25490,25490,"","","‏ ‏قَالَ ‏ ‏قُرَّأتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ بْنِ سَعِيدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ قَالَ ‏ ‏سُئِلَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏وَأَبُو هُرَيْرَةَ ‏ ‏عَنْ الْمُتَوَفَّى عَنْهَا زَوْجُهَا ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏آخِرَ ‏ ‏الْأَجَلَيْنِ ‏ ‏وَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِذَا وَلَدَتْ فَقَدْ ‏ ‏حَلَّتْ ‏ ‏فَدَخَلَ ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَلَى ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهَا عَنْ ذَلِكَ فَقَالَتْ وَلَدَتْ ‏ ‏سُبَيْعَةُ الْأَسْلَمِيَّةُ ‏ ‏بَعْدَ وَفَاةِ ‏ ‏زَوْجِهَا ‏ ‏بِنِصْفِ شَهْرٍ فَخَطَبَهَا رَجُلَانِ أَحَدُهُمَا شَابٌّ وَالْآخَرُ ‏ ‏كَهْلٌ ‏ ‏فَحَطَّتْ ‏ ‏إِلَى الشَّابِّ فَقَالَ ‏ ‏الْكَهْلُ ‏ ‏لَمْ تَحِلَّ وَكَانَ أَهْلُهَا غُيَّبًا وَرَجَا إِذَا جَاءَ أَهْلُهَا أَنْ ‏ ‏يُؤْثِرُوهُ ‏ ‏فَجَاءَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏قَدْ ‏ ‏حَلَلْتِ ‏ ‏فَانْكِحِي مَنْ شِئْتِ ‏","","",""],[25491,25491,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ امْرَأَةً كَانَتْ ‏ ‏تُهَرَاقُ ‏ ‏الدَّمَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَفْتَتْ لَهَا ‏ ‏أُمُّ سَلَمَةَ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لِتَنْظُرْ ‏ ‏عِدَّةَ ‏ ‏اللَّيَالِي وَالْأَيَّامِ الَّتِي كَانَتْ تَحِيضُهُنَّ مِنْ الشَّهْرِ قَبْلَ أَنْ يُصِيبَهَا الَّذِي أَصَابَهَا فَلْتَتْرُكْ الصَّلَاةَ قَدْرَ ذَلِكَ مِنْ الشَّهْرِ فَإِذَا بَلَغَتْ ذَلِكَ فَلْتَغْتَسِلْ ثُمَّ ‏ ‏تَسْتَثْفِرْ ‏ ‏بِثَوْبٍ ثُمَّ تُصَلِّي ‏","","",""],[25492,25492,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَ رَجُلَانِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يَخْتَصِمَانِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَوَارِيثَ بَيْنَهُمَا قَدْ ‏ ‏دُرِسَتْ ‏ ‏لَيْسَ بَيْنَهُمَا بَيِّنَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ ‏ ‏تَخْتَصِمُونَ ‏ ‏إِلَيَّ وَإِنَّمَا أَنَا بَشَرٌ وَلَعَلَّ بَعْضَكُمْ ‏ ‏أَلْحَنُ ‏ ‏بِحُجَّتِهِ ‏ ‏أَوْ قَدْ قَالَ لِحُجَّتِهِ ‏ ‏مِنْ بَعْضٍ فَإِنِّي ‏ ‏أَقْضِي ‏ ‏بَيْنَكُمْ عَلَى نَحْوِ مَا أَسْمَعُ فَمَنْ قَضَيْتُ لَهُ مِنْ حَقِّ أَخِيهِ شَيْئًا فَلَا يَأْخُذْهُ فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنْ النَّارِ يَأْتِي بِهَا ‏ ‏إِسْطَامًا ‏ ‏فِي عُنُقِهِ يَوْمَ الْقِيَامَةِ فَبَكَى الرَّجُلَانِ وَقَالَ كُلُّ وَاحِدٍ مِنْهُمَا حَقِّي لِأَخِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِذْ قُلْتُمَا فَاذْهَبَا فَاقْتَسِمَا ثُمَّ ‏ ‏تَوَخَّيَا ‏ ‏الْحَقَّ ثُمَّ ‏ ‏اسْتَهِمَا ‏ ‏ثُمَّ لِيَحْلِلْ كُلُّ وَاحِدٍ مِنْكُمَا صَاحِبَهُ ‏","","",""],[25493,25493,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏أَحَبُّ الْعَمَلِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا دَامَ عَلَيْهِ وَإِنْ قَلَّ ‏","","",""],[25494,25494,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ فَرُّوخَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُنِي وَهُوَ صَائِمٌ وَأَنَا صَائِمَةٌ ‏","","",""],[25495,25495,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ مَوْلَى الصَّهْبَاءِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ ‏} ‏قَالَ ‏ ‏النَّوْحُ ‏","","",""],[25496,25496,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الصُّفَيْرَا ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ ابْنُ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏لَمَّا تُوُفِّيَ عَنْهَا وَانْقَضَتْ عِدَّتُهَا خَطَبَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ فِيَّ ثَلَاثَ ‏ ‏خِصَالٍ ‏ ‏أَنَا امْرَأَةٌ كَبِيرَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَكْبَرُ مِنْكِ قَالَتْ وَأَنَا امْرَأَةٌ غَيُورٌ قَالَ أَدْعُو اللَّهَ عَزَّ وَجَلَّ فَيُذْهِبُ عَنْكِ غَيْرَتَكِ قَالَتْ يَا رَسُولَ اللَّهِ وَأَنَا امْرَأَةٌ ‏ ‏مُصْبِيَةٌ ‏ ‏قَالَ هُمْ إِلَى اللَّهِ وَإِلَى رَسُولِهِ قَالَ فَتَزَوَّجَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَتَاهَا فَوَجَدَهَا تُرْضِعُ فَانْصَرَفَ ثُمَّ أَتَاهَا فَوَجَدَهَا تُرْضِعُ فَانْصَرَفَ قَالَ فَبَلَغَ ذَلِكَ ‏ ‏عَمَّارَ بْنَ يَاسِرٍ ‏ ‏فَأَتَاهَا فَقَالَ ‏ ‏حُلْتِ ‏ ‏بَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ حَاجَتِهِ هَلُمَّ الصَّبِيَّةَ قَالَ فَأَخَذَهَا فَاسْتَرْضَعَ لَهَا فَأَتَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيْنَ ‏ ‏زُنَابُ ‏ ‏يَعْنِي ‏ ‏زَيْنَبَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ أَخَذَهَا ‏ ‏عَمَّارٌ ‏ ‏فَدَخَلَ بِهَا وَقَالَ إِنَّ بِكِ عَلَى أَهْلِكِ كَرَامَةً قَالَ فَأَقَامَ عِنْدَهَا إِلَى الْعَشِيِّ ثُمَّ قَالَ ‏ ‏إِنْ شِئْتِ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ وَإِنْ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ ‏ ‏سَبَّعْتُ ‏ ‏لِسَائِرِ نِسَائِي وَإِنْ شِئْتِ قَسَمْتُ لَكِ ‏ ‏قَالَتْ لَا بَلْ اقْسِمْ لِي ‏","","",""],[25497,25497,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الصُّفَيْرَا ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ ابْنُ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏لَمَّا تُوُفِّيَ عَنْهَا وَانْقَضَتْ عِدَّتُهَا خَطَبَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ فِيَّ ثَلَاثَ ‏ ‏خِصَالٍ ‏ ‏أَنَا امْرَأَةٌ كَبِيرَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَكْبَرُ مِنْكِ قَالَتْ وَأَنَا امْرَأَةٌ غَيُورٌ قَالَ أَدْعُو اللَّهَ عَزَّ وَجَلَّ فَيُذْهِبُ غَيْرَتَكِ قَالَتْ يَا رَسُولَ اللَّهِ وَإِنِّي امْرَأَةٌ ‏ ‏مُصْبِيَةٌ ‏ ‏قَالَ هُمْ إِلَى اللَّهِ وَرَسُولِهِ قَالَ فَتَزَوَّجَهَا قَالَ فَأَتَاهَا فَوَجَدَهَا تُرْضِعُ فَانْصَرَفَ ثُمَّ أَتَاهَا فَوَجَدَهَا تُرْضِعُ فَانْصَرَفَ قَالَ فَبَلَغَ ذَلِكَ ‏ ‏عَمَّارَ بْنَ يَاسِرٍ ‏ ‏فَأَتَاهَا فَقَالَ ‏ ‏حُلْتِ ‏ ‏بَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ حَاجَتِهِ هَلُمَّ الصَّبِيَّةَ قَالَ فَأَخَذَهَا فَاسْتَرْضَعَ لَهَا فَأَتَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيْنَ ‏ ‏زُنَابُ ‏ ‏يَعْنِي ‏ ‏زَيْنَبَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ أَخَذَهَا ‏ ‏عَمَّارٌ ‏ ‏فَدَخَلَ بِهَا فَقَالَ إِنَّ بِكِ عَلَى أَهْلِكِ كَرَامَةً قَالَ فَأَقَامَ عِنْدَهَا إِلَى الْعَشِيِّ ثُمَّ قَالَ ‏ ‏إِنْ شِئْتِ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ وَإِنْ ‏ ‏سَبَّعْتُ ‏ ‏لَكِ ‏ ‏سَبَّعْتُ ‏ ‏لِسَائِرِ نِسَائِي وَإِنْ شِئْتِ قَسَمْتُ لَكِ قَالَتْ لَا بَلْ اقْسِمْ لِي ‏","","",""],[25498,25498,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ابْنِ ابْنَةِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهُ بَلَغَهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَحَدٍ مِنْ الْمُسْلِمِينَ يُصَابُ بِمُصِيبَةٍ فَيَقُولُ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ ‏ ‏أْجُرْنِي فِي مُصِيبَتِي وَاخْلُفْ عَلَيَّ بِخَيْرٍ مِنْهَا إِلَّا فُعِلَ بِهِ ذَلِكَ ‏ ‏قَالَتْ ‏ ‏فَقُلْتُ ‏ ‏هَذَا ‏ ‏فَآجَرَنِي ‏ ‏اللَّهُ فِي مُصِيبَتِي فَمَنْ يَخْلُفُ عَلَيَّ مَكَانَ ‏ ‏أَبِي سَلَمَةَ ‏ ‏فَلَمَّا ‏ ‏انْقَضَتْ ‏ ‏عِدَّتُهَا خَطَبَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25499,25499,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ طَحْلَاءَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي سَلَمَةَ ‏ ‏إِنَّ ‏ ‏ظِئْرَكَ ‏ ‏سُلَيْمًا ‏ ‏لَا يَتَوَضَّأُ مِمَّا مَسَّتْ النَّارُ قَالَ فَضَرَبَ صَدْرَ ‏ ‏سُلَيْمٍ ‏ ‏وَقَالَ أَشْهَدُ عَلَى ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْهَا كَانَتْ تَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ مِمَّا مَسَّتْ النَّارُ ‏","","",""],[25500,25500,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُوتِرُ ‏ ‏بِسَبْعٍ ‏ ‏أَوْ خَمْسٍ ‏ ‏لَا يَفْصِلُ بَيْنَهُنَّ بِكَلَامٍ وَلَا تَسْلِيمٍ ‏","","",""],[25501,25501,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏وَالَّذِي ذَهَبَ بِنَفْسِهِ ‏ ‏مَا مَاتَ حَتَّى كَانَ أَكْثَرُ صَلَاتِهِ وَهُوَ جَالِسٌ وَكَانَ أَحَبَّ الْأَعْمَالِ إِلَيْهِ الْعَمَلُ الصَّالِحُ الَّذِي يَدُومُ عَلَيْهِ الْعَبْدُ وَإِنْ كَانَ يَسِيرًا ‏","","",""],[25502,25502,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏سَفِينَةَ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَهُوَ فِي الْمَوْتِ ‏ ‏الصَّلَاةَ الصَّلَاةَ وَمَا مَلَكَتْ أَيْمَانُكُمْ فَجَعَلَ يَتَكَلَّمُ بِهَا وَمَا ‏ ‏يَفِيضُ ‏","","",""],[25503,25503,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ضَبَّةَ بْنِ مُحْصِنٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيَكُونُ أُمَرَاءُ يَعْرِفُونَ وَيُنْكِرُونَ فَمَنْ عَرَفَ بَرِئَ وَمَنْ أَنْكَرَ سَلِمَ وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ قَالُوا يَا رَسُولَ اللَّهِ أَفَلَا نُقَاتِلُ ‏ ‏مَجَارَّهُمْ ‏ ‏قَالَ لَا مَا صَلَّوْا ‏","","",""],[25504,25504,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا خَرَجَ مِنْ بَيْتِهِ قَالَ بِسْمِ اللَّهِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَكْبَرُ عِلْمِي أَنَّهُ قَدْ قَالَهَا قَالَ وَقَدْ ذَكَرَهُ ‏ ‏سُفْيَانُ ‏ ‏عَنْهُ وَلَيْسَ فِي بَقِيَّتِهِ شَكٌّ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أَزِلَّ أَوْ أَظْلِمَ أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ ‏","","",""],[25505,25505,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏مَا مَاتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى كَانَ أَكْثَرَ صَلَاتِهِ قَاعِدًا غَيْرَ الْفَرِيضَةِ وَكَانَ أَحَبُّ الْعَمَلِ إِلَيْهِ أَدْوَمَهُ وَإِنْ قَلَّ ‏","","",""],[25506,25506,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏مَوْلًى ‏ ‏لِأُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِذَا صَلَّى الصُّبْحَ حِينَ يُسَلِّمُ اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا ‏","","",""],[25507,25507,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ النَّحْوِيُّ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَرَأَ ‏ { ‏إِنَّهُ عَمِلَ ‏ ‏غَيْرَ ‏ ‏صَالِحٍ ‏}","","",""],[25508,25508,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ يُفْرَشُ لِي ‏ ‏حِيَالَ ‏ ‏مُصَلَّى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏يُصَلِّي وَأَنَا ‏ ‏حِيَالُهُ ‏","","",""],[25509,25509,"","","‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الذَّهَبِ يُرْبَطُ بِهِ ‏ ‏الْمِسْكُ ‏ ‏أَوْ تُرْبَطُ قَالَ ‏ ‏اجْعَلِيهِ فِضَّةً ‏ ‏وَصَفِّرِيهِ ‏ ‏بِشَيْءٍ مِنْ زَعْفَرَانٍ ‏","","",""],[25510,25510,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏لَبِسْتُ ‏ ‏قِلَادَةً ‏ ‏فِيهَا شَعَرَاتٌ مِنْ ذَهَبٍ قَالَتْ فَرَآهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْرَضَ عَنِّي فَقَالَ ‏ ‏مَا يُؤَمِّنُكِ أَنْ يُقَلِّدَكِ اللَّهُ مَكَانَهَا يَوْمَ الْقِيَامَةِ شَعَرَاتٍ مِنْ نَارٍ قَالَتْ فَنَزَعْتُهَا ‏","","",""],[25511,25511,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏يَا رَسُولَ اللَّهِ يَغْزُو الرِّجَالُ وَلَا نَغْزُو وَلَنَا نِصْفُ الْمِيرَاثِ فَأَنْزَلَ اللَّهُ ‏ { ‏وَلَا تَتَمَنَّوْا مَا فَضَّلَ اللَّهُ بِهِ بَعْضَكُمْ عَلَى بَعْضٍ ‏}","","",""],[25512,25512,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ أَبِي مُطِيعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرَتْنِي شَعْرًا مِنْ شَعْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَخْضُوبًا ‏ ‏بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏","","",""],[25513,25513,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ ‏ ‏بِثَلَاثَ عَشْرَةَ فَلَمَّا كَبِرَ وَضَعُفَ ‏ ‏أَوْتَرَ ‏ ‏بِسَبْعٍ ‏","","",""],[25514,25514,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حَضَرْتُمْ الْمَيِّتَ ‏ ‏أَوْ الْمَرِيضَ ‏ ‏فَقُولُوا خَيْرًا فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ ‏","","",""],[25515,25515,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافَعٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏فَاطِمَةَ ‏ ‏اسْتُحِيضَتْ ‏ ‏وَكَانَتْ تَغْتَسِلُ فِي ‏ ‏مِرْكَنٍ ‏ ‏لَهَا فَتَخْرُجُ وَهِيَ عَالِيَةُ الصُّفْرَةِ ‏ ‏وَالْكُدْرَةِ ‏ ‏فَاسْتَفْتَتْ لَهَا ‏ ‏أُمُّ سَلَمَةَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏تَنْتَظِرُ أَيَّامَ ‏ ‏قُرْئِهَا ‏ ‏أَوْ أَيَّامَ ‏ ‏حَيْضِهَا ‏ ‏فَتَدَعُ فِيهِ الصَّلَاةَ وَتَغْتَسِلُ فِيمَا سِوَى ذَلِكَ ‏ ‏وَتَسْتَثْفِرُ ‏ ‏بِثَوْبٍ وَتُصَلِّي ‏","","",""],[25516,25516,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو عَوْنٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَدَّادِ بْنِ الْهَادِ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏كَيْفَ نَسْأَلُ أَحَدًا عَنْ شَيْءٍ وَفِينَا أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْسَلَ إِلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَسَأَلَهَا فَقَالَتْ دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَشَلْتُ لَهُ كَتِفًا مِنْ قِدْرٍ فَأَكَلَ مِنْهَا ثُمَّ خَرَجَ إِلَى الصَّلَاةِ ‏","","",""],[25517,25517,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ قِرَاءَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ فَوَصَفَتْ ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏} ‏حَرْفًا حَرْفًا قِرَاءَةً بَطِيئَةً ‏ ‏قَطَّعَ ‏ ‏عَفَّانُ ‏ ‏قِرَاءَتَهُ ‏","","",""],[25518,25518,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي الْحَذَّاءَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا كَانَتْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لِحَافٍ ‏ ‏فَأَصَابَهَا ‏ ‏الْحَيْضُ فَقَالَ ‏ ‏قُومِي ‏ ‏فَاتَّزِرِي ‏ ‏ثُمَّ عُودِي ‏","","",""],[25519,25519,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَمْزَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏رَأَتْ نَسِيبًا لَهَا يَنْفُخُ إِذَا أَرَادَ أَنْ يَسْجُدَ فَقَالَتْ لَا تَنْفُخْ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِغُلَامٍ لَنَا يُقَالُ لَهُ ‏ ‏رَبَاحٌ ‏ ‏تَرِّبْ ‏ ‏وَجْهَكَ يَا ‏ ‏رَبَاحُ ‏","","",""],[25520,25520,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ يَعْنِي ابْنَ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ أَبِي أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أُخْتِهِ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا فَيَصُومُ وَلَا يُفْطِرُ ‏","","",""],[25521,25521,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِفَاطِمَةَ ‏ ‏ائْتِينِي بِزَوْجِكِ وَابْنَيْكِ فَجَاءَتْ بِهِمْ ‏ ‏فَأَلْقَى ‏ ‏عَلَيْهِمْ ‏ ‏كِسَاءً ‏ ‏فَدَكِيًّا قَالَ ثُمَّ وَضَعَ يَدَهُ عَلَيْهِمْ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ إِنَّ هَؤُلَاءِ آلُ ‏ ‏مُحَمَّدٍ ‏ ‏فَاجْعَلْ صَلَوَاتِكَ وَبَرَكَاتِكَ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَرَفَعْتُ ‏ ‏الْكِسَاءَ ‏ ‏لِأَدْخُلَ مَعَهُمْ فَجَذَبَهُ مِنْ يَدِي وَقَالَ إِنَّكِ عَلَى خَيْرٍ ‏","","",""],[25522,25522,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏عَنْ ‏ ‏الْمُهَاجِرِ ابْنِ الْقِبْطِيَّةِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيُخْسَفَنَّ بِقَوْمٍ يَغْزُونَ هَذَا ‏ ‏الْبَيْتَ ‏ ‏بِبَيْدَاءَ ‏ ‏مِنْ الْأَرْضِ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ يَا رَسُولَ اللَّهِ وَإِنْ كَانَ فِيهِمْ الْكَارِهُ قَالَ يُبْعَثُ كُلُّ رَجُلٍ مِنْهُمْ عَلَى ‏ ‏نِيَّتِهِ ‏","","",""],[25523,25523,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَقَالَتْ لِي أَيُسَبُّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيكُمْ قُلْتُ مَعَاذَ اللَّهِ ‏ ‏أَوْ سُبْحَانَ اللَّهِ أَوْ كَلِمَةً نَحْوَهَا ‏ ‏قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَبَّ ‏ ‏عَلِيًّا ‏ ‏فَقَدْ سَبَّنِي ‏","","",""],[25524,25524,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ وَهُوَ أَبُو شُجَاعٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ هُرْمُزَ الْأَعْرَجَ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏نَاعِمٌ ‏ ‏مَوْلَى ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏سُئِلَتْ أَتَغْتَسِلُ الْمَرْأَةُ مَعَ الرَّجُلِ فَقَالَتْ نَعَمْ إِذَا كَانَتْ ‏ ‏كَيِّسَةً ‏ ‏رَأَيْتُنِي وَرَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَغْتَسِلُ مِنْ ‏ ‏مِرْكَنٍ ‏ ‏وَاحِدٍ ‏ ‏نُفِيضُ ‏ ‏عَلَى أَيْدِينَا حَتَّى نُنْقِيَهَا ثُمَّ نُفِيضُ عَلَيْنَا الْمَاءَ ‏","","",""],[25525,25525,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عُمَرَ بْنِ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ يَوْمَ السَّبْتِ وَيَوْمَ الْأَحَدِ أَكْثَرَ مِمَّا يَصُومُ مِنْ الْأَيَّامِ وَيَقُولُ إِنَّهُمَا عِيدَا الْمُشْرِكِينَ فَأَنَا أُحِبُّ أَنْ أُخَالِفَهُمْ ‏","","",""],[25526,25526,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَحَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَإِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِنِسَائِهِ عَامَ حَجَّةِ الْوَدَاعِ ‏ ‏هَذِهِ ثُمَّ ‏ ‏ظُهُورَ الْحُصْرِ ‏ ‏قَالَ فَكُنَّ كُلُّهُنَّ يَحْجُجْنَ إِلَّا ‏ ‏زَيْنَبَ بِنْتَ جَحْشٍ ‏ ‏وَسَوْدَةَ بِنْتَ زَمْعَةَ ‏ ‏وَكَانَتَا تَقُولَانِ وَاللَّهِ لَا تُحَرِّكُنَا دَابَّةٌ بَعْدَ أَنْ سَمِعْنَا ذَلِكَ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏فِي حَدِيثِهِ قَالَتَا وَاللَّهِ لَا تُحَرِّكُنَا دَابَّةٌ بَعْدَ قَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ ثُمَّ ‏ ‏ظُهُورَ الْحُصْرِ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏بَعْدَ أَنْ سَمِعْنَا ذَلِكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25527,25527,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏أَنَّهَا كَانَتْ تُرَجِّلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَتْ مَرَّةً كُنْتُ ‏ ‏أُرَجِّلُ ‏ ‏رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏مِخْضَبٍ ‏ ‏مِنْ صُفْرٍ ‏","","",""],[25528,25528,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الدَّرَاوَرْدِيُّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ فِي ‏ ‏مِخْضَبٍ ‏ ‏مِنْ صُفْرٍ ‏","","",""],[25529,25529,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ نَافِعٍ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ بِنْتَ أَبِي سَلَمَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّهَا دَخَلَتْ عَلَى ‏ ‏زَيْنَبَ بِنْتِ جَحْشٍ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ ‏ ‏تُحِدَّ ‏ ‏عَلَى مَيِّتٍ فَوْقَ ثَلَاثِ لَيَالٍ إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ‏","","",""],[25530,25530,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْهَجَرِيِّ ‏ ‏عَنْ ‏ ‏جُوَيْرِيَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏جُوَيْرِيَةَ ‏ ‏فِي يَوْمِ جُمُعَةٍ وَهِيَ صَائِمَةٌ فَقَالَ لَهَا ‏ ‏أَصُمْتِ أَمْسِ قَالَتْ لَا قَالَ تَصُومِينَ غَدًا قَالَتْ لَا قَالَ فَأَفْطِرِي ‏","","",""],[25531,25531,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏جُوَيْرِيَةَ بِنْتِ الْحَارِثِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَهِيَ صَائِمَةٌ فَقَالَ ‏ ‏أَصُمْتِ أَمْسِ فَقَالَتْ لَا قَالَ أَتُرِيدِينَ أَنْ تَصُومِي غَدًا قَالَتْ لَا قَالَ فَأَفْطِرِي ‏","","",""],[25532,25532,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏أُمِّ عُثْمَانَ ‏ ‏عَنْ ‏ ‏الطُّفَيْلِ ‏ ‏ابْنِ أَخِي ‏ ‏جُوَيْرِيَةَ ‏ ‏عَنْ ‏ ‏جُوَيْرِيَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ ثَوْبَ حَرِيرٍ أَلْبَسَهُ اللَّهُ ثَوْبًا مِنْ النَّارِ يَوْمَ الْقِيَامَةِ ‏","","",""],[25533,25533,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏آلِ ‏ ‏طَلْحَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏كُرَيْبًا ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏جُوَيْرِيَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏أَتَى عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُدْوَةً ‏ ‏وَأَنَا أُسَبِّحُ ثُمَّ انْطَلَقَ ‏ ‏لِحَاجَةٍ ‏ ‏ثُمَّ رَجَعَ قَرِيبًا مِنْ نِصْفِ النَّهَارِ فَقَالَ مَا زِلْتِ قَاعِدَةً قُلْتُ نَعَمْ فَقَالَ أَلَا أُعَلِّمُكِ كَلِمَاتٍ لَوْ عُدِلْنَ بِهِنَّ عَدَلَتْهُنَّ أَوْ لَوْ وُزِنَّ بِهِنَّ وَزَنَتْهُنَّ ‏ ‏يَعْنِي بِجَمِيعِ مَا سَبَّحَتْ ‏ ‏سُبْحَانَ اللَّهِ عَدَدَ خَلْقِهِ ثَلَاثَ مَرَّاتٍ سُبْحَانَ اللَّهِ زِنَةَ عَرْشِهِ ثَلَاثَ مَرَّاتٍ سُبْحَانَ اللَّهِ رِضَا نَفْسِهِ ثَلَاثَ مَرَّاتٍ سُبْحَانَ اللَّهِ مِدَادَ كَلِمَاتِهِ ثَلَاثَ مَرَّاتٍ ‏","","",""],[25534,25534,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏وَجَدَ رِيحَ طِيبٍ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏فَقَالَ مِمَّنْ هَذِهِ الرِّيحُ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏مِنِّي يَا أَمِيرَ الْمُؤْمِنِينَ فَقَالَ مِنْكَ لِعَمْرِي فَقَالَ طَيَّبَتْنِي ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏وَزَعَمَتْ أَنَّهَا ‏ ‏طَيَّبَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ إِحْرَامِهِ فَقَالَ اذْهَبْ فَأَقْسِمْ عَلَيْهَا لَمَا غَسَلَتْهُ فَرَجَعَ إِلَيْهَا فَغَسَلَتْهُ ‏","","",""],[25535,25535,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ حُدَيْجٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي الثَّوْبِ الَّذِي يَنَامُ مَعَكِ فِيهِ قَالَتْ نَعَمْ مَا لَمْ يَرَ فِيهِ أَذًى ‏","","",""],[25536,25536,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ضَمْرَةُ بْنُ حَبِيبٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ أَبِي سُفْيَانَ الثَّقَفِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أُمَّ حَبِيبَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَعَلَيَّ وَعَلَيْهِ ثَوْبٌ وَاحِدٌ فِيهِ كَانَ مَا كَانَ ‏","","",""],[25537,25537,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ شَكَلٍ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏","","",""],[25538,25538,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ بْنِ يَزِيدَ بْنِ رُكَانَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِي الْجَرَّاحِ ‏ ‏مَوْلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏أَنَّهَا حَدَّثَتْهُ قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ كَمَا يَتَوَضَّئُونَ ‏","","",""],[25539,25539,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَ ‏ ‏عَنْبَسَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏الْمَوْتُ اشْتَدَّ ‏ ‏جَزَعُهُ ‏ ‏فَقِيلَ لَهُ مَا هَذَا ‏ ‏الْجَزَعُ ‏ ‏قَالَ إِنِّي سَمِعْتُ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏يَعْنِي أُخْتَهُ ‏ ‏تَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى أَرْبَعًا قَبْلَ الظُّهْرِ وَأَرْبَعًا بَعْدَهَا حَرَّمَ اللَّهُ لَحْمَهُ عَلَى النَّارِ فَمَا تَرَكْتُهُنَّ مُنْذُ سَمِعْتُهُنَّ ‏","","",""],[25540,25540,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ نَافِعٍ ‏ ‏أَنَّ ‏ ‏زَيْنَبَ بِنْتَ أَبِي سَلَمَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّهَا دَخَلَتْ عَلَى ‏ ‏أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ ‏ ‏فَقَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ ‏ ‏تُحِدَّ ‏ ‏عَلَى مَيِّتٍ فَوْقَ ثَلَاثِ لَيَالٍ إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حُمَيْدُ بْنُ نَافِعٍ أَبُو أَفْلَحَ وَهُوَ حُمَيْدٌ صَفِيرَا ‏","","",""],[25541,25541,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ نَافِعٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْنَبَ بِنْتَ أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏تُوُفِّيَ ‏ ‏حَمِيمٌ ‏ ‏لِأُمِّ حَبِيبَةَ ‏ ‏فَدَعَتْ ‏ ‏بِصُفْرَةٍ ‏ ‏فَمَسَحَتْ بِذِرَاعَيْهَا وَقَالَتْ إِنَّمَا أَصْنَعُ هَذَا لِشَيْءٍ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏لِأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ مُسْلِمَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ ‏ ‏تُحِدَّ ‏ ‏فَوْقَ ثَلَاثٍ إِلَّا عَلَى زَوْجِهَا أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ‏ ‏وَحَدَّثَتْهُ ‏ ‏زَيْنَبُ ‏ ‏عَنْ ‏ ‏أُمِّهَا ‏ ‏وَعَنْ ‏ ‏زَيْنَبَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏امْرَأَةٍ مِنْ بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25542,25542,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا سَمِعَ الْمُؤَذِّنَ يُؤَذِّنُ قَالَ كَمَا يَقُولُ حَتَّى يَسْكُتَ ‏","","",""],[25543,25543,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏حَدَّثَتْ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ صَلَّى فِي يَوْمٍ ثِنْتَيْ عَشْرَةَ رَكْعَةً بَنَى اللَّهُ لَهُ ‏ ‏أَوْ بُنِيَ لَهُ ‏ ‏بَيْتٌ فِي الْجَنَّةِ ‏","","",""],[25544,25544,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى فِي يَوْمٍ وَلَيْلَةٍ ثِنْتَيْ عَشْرَةَ سَجْدَةً سِوَى الْمَكْتُوبَةِ بُنِيَ لَهُ بَيْتٌ فِي الْجَنَّةِ ‏","","",""],[25545,25545,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ قَالَ ‏ ‏نَافِعٌ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏أَبَا الْجَرَّاحِ ‏ ‏مَوْلَى ‏ ‏أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْعِيرَ ‏ ‏الَّتِي فِيهَا الْجَرَسُ لَا تَصْحَبُهَا الْمَلَائِكَةُ ‏","","",""],[25546,25546,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ سَمِعْتُهُ يُحَدِّثُ ‏ ‏يَعْنِي ‏ ‏أَبَاهُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ بْنِ الْهَادِ ‏ ‏أَنَّ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا الْجَرَّاحِ ‏ ‏مَوْلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أُمَّ حَبِيبَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ قَوْمًا فِيهِمْ جَرَسٌ ‏","","",""],[25547,25547,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَكْحُولٌ ‏ ‏أَنَّ ‏ ‏مَوْلًى لِعَنْبَسَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَنْبَسَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَلَّى أَرْبَعًا قَبْلَ الظُّهْرِ وَأَرْبَعًا بَعْدَ الظُّهْرِ حَرَّمَهُ اللَّهُ عَلَى النَّارِ ‏","","",""],[25548,25548,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ يَزِيدَ الْعَطَّارَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ سَعِيدِ بْنِ الْمُغِيرَةِ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَقَتْهُ قَدَحًا مِنْ ‏ ‏سَوِيقٍ ‏ ‏فَدَعَا بِمَاءٍ فَمَضْمَضَ فَقَالَتْ لَهُ يَا ابْنَ أَخِي أَلَا تَتَوَضَّأُ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ أَوْ غَيَّرَتْ ‏","","",""],[25549,25549,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ يَعْنِي ابْنَ فَضَالَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏أَنَّهُ قَالَ حَدَّثَنَا ‏ ‏عَنْبَسَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ حَبِيبَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏تَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَلَّى ثِنْتَيْ عَشْرَةَ رَكْعَةً فِي لَيْلِهِ وَنَهَارِهِ غَيْرَ الْمَكْتُوبَةِ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ ‏","","",""],[25550,25550,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أُخْتِهِ ‏ ‏أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ مُسْلِمٍ ‏ ‏يُصَلِّي لِلَّهِ عَزَّ وَجَلَّ كُلَّ يَوْمٍ ثِنْتَيْ عَشْرَةَ رَكْعَةً تَطَوُّعًا غَيْرَ فَرِيضَةٍ إِلَّا بُنِيَ لَهُ بَيْتٌ فِي الْجَنَّةِ ‏ ‏أَوْ بَنَى اللَّهُ عَزَّ وَجَلَّ لَهُ بِهِنَّ بَيْتًا فِي الْجَنَّةِ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏فَمَا ‏ ‏بَرِحْتُ ‏ ‏أُصَلِّيهِنَّ بَعْدُ ‏ ‏و قَالَ ‏ ‏عَمْرٌو ‏ ‏مَا ‏ ‏بَرِحْتُ ‏ ‏أُصَلِّيهِنَّ بَعْدُ ‏ ‏و قَالَ ‏ ‏النُّعْمَانُ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[25551,25551,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنِ ‏ ‏ابْنِ شَوَّالٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏فَأَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدِمَهَا مِنْ ‏ ‏جَمْعٍ ‏ ‏بِلَيْلٍ ‏","","",""],[25552,25552,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْجَرَّاحِ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جَرَسٌ ‏","","",""],[25553,25553,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ أَخْنَسَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ خَالَتَهُ ‏ ‏قَالَ سَقَتْنِي ‏ ‏سَوِيقًا ‏ ‏ثُمَّ قَالَتْ لَا تَخْرُجْ حَتَّى تَتَوَضَّأَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[25554,25554,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[25555,25555,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي جَرَّاحٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْعِيرَ ‏ ‏الَّتِي فِيهَا جَرَسٌ لَا تَصْحَبُهَا الْمَلَائِكَةُ ‏","","",""],[25556,25556,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ أَوْسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَنْبَسَةَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ عَبْدٍ مُسْلِمٍ تَوَضَّأَ فَأَسْبَغَ الْوُضُوءَ ثُمَّ صَلَّى لِلَّهِ عَزَّ وَجَلَّ كُلَّ يَوْمٍ ثِنْتَيْ عَشْرَةَ رَكْعَةً إِلَّا بُنِيَ لَهُ بَيْتٌ فِي الْجَنَّةِ ‏ ‏قَالَتْ ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏فَمَا زِلْتُ ‏ ‏أُصَلِّيهِنَّ بَعْدُ ‏ ‏و قَالَ ‏ ‏عَنْبَسَةُ ‏ ‏فَمَا زِلْتُ ‏ ‏أُصَلِّيهِنَّ بَعْدُ ‏ ‏و قَالَ ‏ ‏عَمْرُو بْنُ أَوْسٍ ‏ ‏فَمَا زِلْتُ ‏ ‏أُصَلِّيهِنَّ ‏ ‏قَالَ ‏ ‏النُّعْمَانُ ‏ ‏وَأَنَا لَا أَكَادُ أَدَعُهُنَّ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ مُسْلِمٍ ‏ ‏يُصَلِّي لِلَّهِ عَزَّ وَجَلَّ كُلَّ يَوْمٍ ثِنْتَيْ عَشْرَةَ رَكْعَةً تَطَوُّعًا غَيْرَ فَرِيضَةٍ فَذَكَرَ نَحْوَهُ ‏","","",""],[25557,25557,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيٌّ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ سَعِيدٍ الْأَخْنَسِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏فَدَعَتْ لِي ‏ ‏بِسَوِيقٍ ‏ ‏فَشَرِبْتُهُ فَقَالَتْ أَلَا تَتَوَضَّأُ فَقُلْتُ إِنِّي لَمْ أُحْدِثْ قَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[25558,25558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ الْمُغِيرَةِ بْنِ الْأَخْنَسِ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏فَسَقَتْهُ ‏ ‏سَوِيقًا ‏ ‏ثُمَّ قَامَ ‏ ‏يُصَلِّي فَقَالَتْ لَهُ تَوَضَّأْ يَا ابْنَ أَخِي فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَبُو سُفْيَانَ بْنُ سَعِيدِ بْنِ الْأَخْنَسِ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ خَالَةُ ‏ ‏أَبِي سُفْيَانَ بْنِ سَعِيدٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[25559,25559,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُسْلِمِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ سَعِيدِ بْنِ الْأَخْنَسِ بْنِ شَرِيقٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏وَكَانَتْ خَالَتَهُ فَسَقَتْنِي شَرْبَةً مِنْ ‏ ‏سَوِيقٍ ‏ ‏فَلَمَّا قُمْتُ قَالَتْ لِي أَيْ بُنَيَّ لَا تُصَلِّيَنَّ حَتَّى تَتَوَضَّأَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَمَرَنَا أَنْ نَتَوَضَّأَ مِمَّا مَسَّتْ النَّارُ مِنْ الطَّعَامِ ‏","","",""],[25560,25560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏مُصْعَبٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏وَمُجَمِّعٍ ‏ ‏ابْنَيْ ‏ ‏يَزِيدَ ابْنِ جَارِيَةَ ‏ ‏عَنْ ‏ ‏خَنْسَاءَ بِنْتِ خِذَامٍ ‏ ‏أَنَّ أَبَاهَا زَوَّجَهَا وَهِيَ كَارِهَةٌ وَكَانَتْ ‏ ‏ثَيِّبًا ‏ ‏فَرَدَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِكَاحَهُ ‏","","",""],[25561,25561,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏وَمُجَمِّعٍ ‏ ‏شَيْخَيْنِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَّ ‏ ‏خَنْسَاءَ ‏ ‏أَنْكَحَهَا أَبُوهَا وَكَرِهَتْ ذَلِكَ فَرَدَّهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[25562,25562,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُجَمِّعِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أُمِّ مُجَمِّعٍ ‏ ‏قَالَ زَوَّجَ ‏ ‏خِدَامٌ ‏ ‏ابْنَتَهُ ‏ ‏وَهِيَ كَارِهَةٌ فَأَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ أَبِي زَوَّجَنِي وَأَنَا كَارِهَةٌ قَالَ فَرَدَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِكَاحَ أَبِيهَا ‏","","",""],[25563,25563,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ الْأَنْصَارِيَّ ‏ ‏وَمُجَمِّعَ بْنَ يَزِيدَ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَاهُ ‏ ‏أَنَّ رَجُلًا مِنْهُمْ يُدْعَى ‏ ‏خِذَامًا ‏ ‏أَنْكَحَ ابْنَةً لَهُ فَكَرِهَتْ نِكَاحَ أَبِيهَا فَأَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ ذَلِكَ لَهُ فَرَدَّ عَنْهَا نِكَاحَ أَبِيهَا فَتَزَوَّجَتْ ‏ ‏أَبَا لُبَابَةَ بْنَ عَبْدِ الْمُنْذِرِ ‏ ‏فَذَكَرَ ‏ ‏يَحْيَى ‏ ‏أَنَّهُ بَلَغَهُ أَنَّهَا كَانَتْ ‏ ‏ثَيِّبًا ‏","","",""],[25564,25564,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏يَعْقُوبَ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَجَّاجُ بْنُ السَّائِبِ بْنِ أَبِي لُبَابَةَ بْنِ عَبْدِ الْمُنْذِرِ الْأَنْصَارِيُّ ‏ ‏أَنَّ ‏ ‏جَدَّتَهُ ‏ ‏أُمَّ السَّائِبِ خُنَاسَ بِنْتِ خِذَامِ بْنِ خَالِدٍ ‏ ‏كَانَتْ عِنْدَ رَجُلٍ قَبْلَ ‏ ‏أَبِي لُبَابَةَ ‏ ‏تَأَيَّمَتْ ‏ ‏مِنْهُ فَزَوَّجَهَا أَبُوهَا ‏ ‏خِذَامُ بْنُ خَالِدٍ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفِ بْنِ الْخَزْرَجِ ‏ ‏فَأَبَتْ ‏ ‏إِلَّا أَنْ تَحُطَّ إِلَى ‏ ‏أَبِي لُبَابَةَ ‏ ‏وَأَبَى أَبُوهَا إِلَّا أَنْ يُلْزِمَهَا ‏ ‏الْعَوْفِيَّ ‏ ‏حَتَّى ارْتَفَعَ أَمْرُهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيَ أَوْلَى بِأَمْرِهَا فَأَلْحِقْهَا بِهَوَاهَا قَالَ فَانْتُزِعَتْ مِنْ ‏ ‏الْعَوْفِيِّ ‏ ‏وَتَزَوَّجَتْ ‏ ‏أَبَا لُبَابَةَ ‏ ‏فَوَلَدَتْ لَهُ ‏ ‏أَبَا السَّائِبِ بْنَ أَبِي لُبَابَةَ ‏","","",""],[25565,25565,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏أَبِي ‏ ‏: ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ السَّائِبِ بْنِ أَبِي لُبَابَةَ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏خُنَاسُ بِنْتُ خِذَامٍ ‏ ‏عِنْدَ رَجُلٍ ‏ ‏تَأَيَّمَتْ ‏ ‏مِنْهُ فَزَوَّجَهَا أَبُوهَا رَجُلًا مِنْ ‏ ‏بَنِي عَوْفٍ ‏ ‏وَحَطَّتْ ‏ ‏هِيَ إِلَى ‏ ‏أَبِي لُبَابَةَ ‏ ‏فَأَبَى أَبُوهَا إِلَّا أَنْ يُلْزِمَهَا ‏ ‏الْعَوْفِيَّ ‏ ‏وَأَبَتْ هِيَ حَتَّى ارْتَفَعَ شَأْنُهُمَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏هِيَ أَوْلَى بِأَمْرِهَا فَأَلْحِقْهَا بِهَوَاهَا فَتَزَوَّجَتْ ‏ ‏أَبَا لُبَابَةَ ‏ ‏فَوَلَدَتْ لَهُ ‏ ‏أَبَا السَّائِبِ ‏","","",""],[25566,25566,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ حَبِيبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ طَلْحَةَ بْنِ يَزِيدَ بْنِ رُكَانَةَ ‏ ‏أَنَّ ‏ ‏خَالَتَهُ ‏ ‏أُخْتَ مَسْعُودِ ابْنِ الْعَجْمَاءِ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ أَبَاهَا قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَخْزُومِيَّةِ الَّتِي سَرَقَتْ ‏ ‏قَطِيفَةً ‏ ‏نَفْدِيهَا بِأَرْبَعِينَ ‏ ‏أُوقِيَّةً ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ تَطَّهَّرَ خَيْرٌ لَهَا فَأَمَرَ بِهَا فَقُطِعَتْ يَدُهَا وَهِيَ مِنْ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏أَوْ مِنْ ‏ ‏بَنِي عَبْدِ الْأَسَدِ ‏","","",""],[25567,25567,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُوسُفُ بْنُ الْمَاجِشُونِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏رُمَيْثَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَلَوْ أَشَاءُ أَنْ أُقَبِّلَ الْخَاتَمَ الَّذِي بَيْنَ كَتِفَيْهِ مِنْ قُرْبِي مِنْهُ لَفَعَلْتُ يَقُولُ اهْتَزَّ لَهُ عَرْشُ الرَّحْمَنِ تَبَارَكَ وَتَعَالَى يُرِيدُ ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏يَوْمَ تُوُفِّيَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُوسُفُ بْنُ الْمَاجِشُونِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ الظَّفَرِيِّ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏رُمَيْثَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[25568,25568,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِشَاةٍ ‏ ‏لِمَوْلَاةٍ ‏ ‏لِمَيْمُونَةَ ‏ ‏مَيِّتَةٍ فَقَالَ ‏ ‏أَلَا أَخَذُوا ‏ ‏إِهَابَهَا ‏ ‏فَدَبَغُوهُ ‏ ‏فَانْتَفَعُوا بِهِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّهَا مَيْتَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا حُرِّمَ أَكْلُهَا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏هَذِهِ الْكَلِمَةُ لَمْ أَسْمَعْهَا إِلَّا مِنْ ‏ ‏الزُّهْرِيِّ ‏ ‏حُرِّمَ أَكْلُهَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّتَيْنِ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏","","",""],[25569,25569,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ فَأْرَةً وَقَعَتْ فِي سَمْنٍ فَمَاتَتْ فَسُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خُذُوهَا وَمَا حَوْلَهَا فَأَلْقُوهُ وَكُلُوهُ ‏","","",""],[25570,25570,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ جَابِرٍ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[25571,25571,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اغْتَسَلَ مِنْ الْجَنَابَةِ يَبْدَأُ فَيَغْسِلُ يَدَيْهِ ثُمَّ ‏ ‏يُفْرِغُ ‏ ‏بِيَمِينِهِ عَلَى شِمَالِهِ فَيَغْسِلُ فَرْجَهُ ثُمَّ يَضْرِبُ يَدَهُ عَلَى الْأَرْضِ فَيَمْسَحُهَا ثُمَّ يَغْسِلُهَا ثُمَّ يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يُفْرِغُ عَلَى رَأْسِهِ وَعَلَى سَائِرِ جَسَدِهِ ثُمَّ ‏ ‏يَتَنَحَّى فَيَغْسِلُ رِجْلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو الرَّبِيعِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[25572,25572,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ السَّبَّاقِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاثِرًا ‏ ‏فَقِيلَ لَهُ مَا لَكَ يَا رَسُولَ اللَّهِ أَصْبَحْتَ ‏ ‏خَاثِرًا ‏ ‏قَالَ وَعَدَنِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَنْ ‏ ‏يَلْقَانِي فَلَمْ يَلْقَنِي وَمَا أَخْلَفَنِي فَلَمْ يَأْتِهِ تِلْكَ اللَّيْلَةَ وَلَا الثَّانِيَةَ وَلَا الثَّالِثَةَ ثُمَّ اتَّهَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَرْوَ ‏ ‏كَلْبٍ وَكَانَ تَحْتَ ‏ ‏نَضَدِنَا ‏ ‏فَأَمَرَ بِهِ فَأُخْرِجَ ثُمَّ أَخَذَ مَاءً فَرَشَّ مَكَانَهُ فَجَاءَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ ‏ ‏وَعَدْتَنِي فَلَمْ أَرَكَ قَالَ إِنَّا لَا نَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةٌ فَأَمَرَ يَوْمَئِذٍ بِقَتْلِ الْكِلَابِ قَالَ حَتَّى كَانَ يُسْتَأْذَنُ فِي كَلْبِ ‏ ‏الْحَائِطِ ‏ ‏الصَّغِيرِ فَيَأْمُرُ بِهِ أَنْ يُقْتَلَ ‏","","",""],[25573,25573,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏ ‏بِفَضْلِ ‏ ‏غُسْلِهَا مِنْ الْجَنَابَةِ ‏","","",""],[25574,25574,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏أَجْنَبْتُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاغْتَسَلْتُ مِنْ ‏ ‏جَفْنَةٍ ‏ ‏فَفَضَلَتْ ‏ ‏فَضْلَةٌ ‏ ‏فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَغْتَسِلَ مِنْهَا فَقُلْتُ إِنِّي قَدْ اغْتَسَلْتُ مِنْهَا فَقَالَ ‏ ‏إِنَّ الْمَاءَ لَيْسَ عَلَيْهِ جَنَابَةٌ ‏ ‏أَوْ لَا يُنَجِّسُهُ شَيْءٌ ‏ ‏فَاغْتَسَلَ مِنْهُ ‏","","",""],[25575,25575,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا اسْتَفْتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي فَأْرَةٍ سَقَطَتْ فِي سَمْنٍ لَهُمْ جَامِدٍ فَقَالَ ‏ ‏أَلْقُوهَا وَمَا حَوْلَهَا وَكُلُوا سَمْنَكُمْ ‏","","",""],[25576,25576,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى وَعَلَيْهِ ‏ ‏مِرْطٌ ‏ ‏لِبَعْضِ نِسَائِهِ وَعَلَيْهَا بَعْضُهُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏أُرَاهُ قَالَ حَائِضٍ ‏","","",""],[25577,25577,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[25578,25578,"","","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى الرَّاسِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الشَّيْبَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادِ بْنِ الْهَادِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ خَالَتِي ‏ ‏مَيْمُونَةَ بِنْتَ الْحَارِثِ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تَكُونُ حَائِضًا وَهِيَ ‏ ‏مُفْتَرِشَةٌ ‏ ‏بِحِذَاءِ ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي عَلَى ‏ ‏خُمْرَتِهِ ‏ ‏إِذَا سَجَدَ أَصَابَنِي طَرَفُ ثَوْبِهِ ‏","","",""],[25579,25579,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الشَّيْبَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ فَيُصَلِّي مِنْ اللَّيْلِ وَأَنَا نَائِمَةٌ إِلَى جَنْبِهِ فَإِذَا سَجَدَ أَصَابَنِي ثِيَابُهُ وَأَنَا حَائِضٌ ‏","","",""],[25580,25580,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏ ‏فَيَسْجُدُ فَيُصِيبُنِي ثَوْبُهُ وَأَنَا إِلَى جَنْبِهِ وَأَنَا حَائِضٌ ‏","","",""],[25581,25581,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ الْأَصَمِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏اسْمُهُ ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ابْنِ أَخِي يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏وَهِيَ خَالَتُهُ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ وَثَمَّ ‏ ‏بَهْمَةٌ ‏ ‏أَرَادَتْ أَنْ تَمُرَّ بَيْنَ يَدَيْهِ ‏ ‏تَجَافَى ‏","","",""],[25582,25582,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْبُوذٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏كُنْتُ عِنْدَ ‏ ‏مَيْمُونَةَ ‏ ‏فَأَتَاهَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقَالَتْ يَا بُنَيَّ مَا لَكَ ‏ ‏شَعِثًا ‏ ‏رَأْسُكَ قَالَ ‏ ‏أُمُّ عَمَّارٍ ‏ ‏مُرَجِّلَتِي ‏ ‏حَائِضٌ قَالَتْ أَيْ بُنَيَّ وَأَيْنَ الْحَيْضَةُ مِنْ الْيَدِ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَى إِحْدَانَا وَهِيَ حَائِضٌ فَيَضَعُ رَأْسَهُ فِي حِجْرِهَا فَيَقْرَأُ الْقُرْآنَ وَهِيَ حَائِضٌ ثُمَّ تَقُومُ إِحْدَانَا ‏ ‏بِخُمْرَتِهِ ‏ ‏فَتَضَعُهَا فِي الْمَسْجِدِ وَهِيَ حَائِضٌ أَيْ بُنَيَّ وَأَيْنَ الْحَيْضَةُ مِنْ الْيَدِ ‏","","",""],[25583,25583,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْبُوذٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏سَمِعَتْهُ ‏ ‏مِنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏وَكَانَتْ إِحْدَانَا ‏ ‏تَبْسُطُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخُمْرَةَ ‏ ‏وَهِيَ حَائِضٌ ثُمَّ ‏ ‏يُصَلِّي عَلَيْهَا ‏","","",""],[25584,25584,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكَّارٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَلَى جَنَازَةٍ فَقَالَ أَقِيمُوا صُفُوفَكُمْ وَلْتَحْسُنْ شَفَاعَتُكُمْ وَلَوْ اخْتَرْتُ رَجُلًا اخْتَرْتُهُ ثُمَّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَلِيطٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ الْحَدَّادُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَلِيطٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَيْمُونَةَ ‏ ‏وَكَانَ أَخَاهَا مِنْ الرَّضَاعَةِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ ‏ ‏يُصَلِّي عَلَيْهِ أُمَّةٌ إِلَّا شُفِّعُوا فِيهِ ‏ ‏و قَالَ ‏ ‏أَبُو الْمَلِيحِ ‏ ‏الْأُمَّةُ أَرْبَعُونَ إِلَى مِائَةٍ فَصَاعِدًا ‏","","",""],[25585,25585,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرٌ ‏ ‏أَنَّ ‏ ‏كُرَيْبًا ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏أَكَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ كَتِفٍ ثُمَّ قَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[25586,25586,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏وَحَدَّثَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏خَالِدَ بْنَ الْوَلِيدِ ‏ ‏دَخَلَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏وَهِيَ حَائِضٌ فَقُدِّمَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَحْمُ ضَبٍّ جَاءَتْ بِهِ ‏ ‏أُمُّ حُفَيْدٍ ابْنَةُ الْحَارِثِ ‏ ‏مِنْ ‏ ‏نَجْدٍ ‏ ‏وَكَانَتْ تَحْتَ رَجُلٍ مِنْ ‏ ‏بَنِي جَعْفَرٍ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْكُلُ شَيْئًا حَتَّى يَعْلَمَ مَا هُوَ فَقَالَ بَعْضُ النِّسْوَةِ أَلَا تُخْبِرِينَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَأْكُلُ ‏ ‏فَأَخْبَرَتْهُ أَنَّهُ لَحْمُ ضَبٍّ فَتَرَكَهُ قَالَ ‏ ‏خَالِدٌ ‏ ‏فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَرَامٌ هُوَ قَالَ لَا وَلَكِنَّهُ طَعَامٌ لَيْسَ فِي قَوْمِي فَأَجِدُنِي ‏ ‏أَعَافُهُ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏فَاجْتَرَرْتُهُ ‏ ‏إِلَيَّ فَأَكَلْتُهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرُ ‏ ‏قَالَ ‏ ‏وَحَدَّثَهُ ‏ ‏الْأَصَمُّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏وَكَانَ فِي ‏ ‏حِجْرِهَا ‏ ‏يَعْنِي بِهَذَا الْحَدِيثِ ‏ ‏وَأَظُنُّ أَنَّ ‏ ‏الْأَصَمَّ ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏","","",""],[25587,25587,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ يَعْنِي ابْنَ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏تَزَوَّجَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ حَلَالٌ بَعْدَمَا رَجَعْنَا مِنْ ‏ ‏مَكَّةَ ‏","","",""],[25588,25588,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ حَسِبْتُهُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏أَنَّهَا اسْتَدَانَتْ دَيْنًا فَقِيلَ لَهَا تَسْتَدِينِينَ وَلَيْسَ عِنْدَكِ وَفَاؤُهُ قَالَتْ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ أَحَدٍ يَسْتَدِينُ دَيْنًا يَعْلَمُ اللَّهُ أَنَّهُ يُرِيدُ أَدَاءَهُ إِلَّا أَدَّاهُ ‏","","",""],[25589,25589,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏أَعْتَقْتُ جَارِيَةً لِي فَدَخَلَ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِعِتْقِهَا فَقَالَ ‏ ‏آجَرَكِ اللَّهُ أَمَا إِنَّكِ لَوْ كُنْتِ أَعْطَيْتِهَا أَخْوَالَكِ كَانَ أَعْظَمَ لِأَجْرِكِ ‏","","",""],[25590,25590,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ ‏ ‏جَافَى ‏ ‏حَتَّى يَرَى مَنْ خَلْفَهُ ‏ ‏بَيَاضَ ‏ ‏إِبْطَيْهِ ‏","","",""],[25591,25591,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏بُدَيَّةَ ‏ ‏قَالَتْ ‏ ‏أَرْسَلَتْنِي ‏ ‏مَيْمُونَةُ بِنْتُ الْحَارِثِ ‏ ‏إِلَى ‏ ‏امْرَأَةِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏وَكَانَتْ بَيْنَهُمَا قَرَابَةٌ فَرَأَيْتُ فِرَاشَهَا مُعْتَزِلًا فِرَاشَهُ فَظَنَنْتُ أَنَّ ذَلِكَ لِهِجْرَانٍ فَسَأَلْتُهَا فَقَالَتْ لَا وَلَكِنِّي حَائِضٌ فَإِذَا حِضْتُ لَمْ يَقْرَبْ فِرَاشِي فَأَتَيْتُ ‏ ‏مَيْمُونَةَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهَا فَرَدَّتْنِي إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقَالَتْ أَرَغْبَةً عَنْ سُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ مَعَ الْمَرْأَةِ مِنْ نِسَائِهِ الْحَائِضِ وَمَا بَيْنَهُمَا إِلَّا ثَوْبٌ مَا يُجَاوِزُ الرُّكْبَتَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏مَوْلَى ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏بُدَيَّةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[25592,25592,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَزْهَرَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ السَّائِبِ ابْنِ أَخِي مَيْمُونَةَ الْهِلَالِيَّةِ ‏ ‏أَنَّهُ حَدَّثَهُ أَنَّ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ لَهُ يَا ابْنَ أَخِي أَلَا ‏ ‏أَرْقِيكَ بِرُقْيَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى قَالَتْ ‏ ‏بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ وَاللَّهُ ‏ ‏يَشْفِيكَ مِنْ كُلِّ دَاءٍ فِيكَ أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ وَاشْفِ أَنْتَ الشَّافِي لَا شَافِيَ إِلَّا أَنْتَ ‏","","",""],[25593,25593,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ سَمِعْتُ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏أَعْتَقْتُ ‏ ‏وَلِيدَةً ‏ ‏فِي زَمَانِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَعْطَيْتِهَا أَخْوَالَكِ كَانَ أَعْظَمَ لِأَجْرِكِ ‏","","",""],[25594,25594,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ يَعْنِي ابْنَ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَعَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏تَنْبِذُوا ‏ ‏فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَلَا فِي ‏ ‏الْمُزَفَّتِ ‏ ‏وَلَا فِي ‏ ‏الْحَنْتَمِ ‏ ‏وَلَا فِي ‏ ‏النَّقِيرِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَلَا فِي ‏ ‏الْجِرَارِ ‏ ‏وَكُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[25595,25595,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْجَرِّ ‏ ‏وَالْمُقَيَّرِ ‏ ‏وَقَالَ كُلُّ مُسْكِرٍ حَرَامٌ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[25596,25596,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ مَعْبَدِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ امْرَأَةً اشْتَكَتْ شَكْوَى فَقَالَتْ لَئِنْ شَفَانِي اللَّهُ لَأَخْرُجَنَّ فَلَأُصَلِّيَنَّ فِي ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَبَرِئَتْ ‏ ‏فَتَجَهَّزَتْ تُرِيدُ الْخُرُوجَ فَجَاءَتْ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسَلِّمُ عَلَيْهَا فَأَخْبَرَتْهَا ذَلِكَ فَقَالَتْ اجْلِسِي فَكُلِي مَا صَنَعْتُ وَصَلِّي فِي ‏ ‏مَسْجِدِ الرَّسُولِ ‏ ‏فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةٌ فِيهِ أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏مَسْجِدَ الْكَعْبَةِ ‏","","",""],[25597,25597,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ إِسْحَاقَ بْنِ يَسَارٍ ‏ ‏قَالَ قَرَأْتُ ‏ ‏فِي كِتَابٍ ‏ ‏لِعَطَاءِ بْنِ يَسَارٍ ‏ ‏مَعَ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏فَسَأَلْتُ ‏ ‏مَيْمُونَةَ زَوْجَ النَّبِيِّ ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَكُلَّ سَاعَةٍ يَمْسَحُ الْإِنْسَانُ عَلَى الْخُفَّيْنِ وَلَا يَنْزِعُهُمَا قَالَ نَعَمْ ‏","","",""],[25598,25598,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا فَزَارَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَهَا حَلَالًا وَبَنَى بِهَا حَلَالًا وَمَاتَتْ ‏ ‏بِسَرِفَ ‏ ‏فَدَفَنَهَا فِي ‏ ‏الظُّلَّةِ ‏ ‏الَّتِي بَنَى بِهَا فِيهَا فَنَزَلْنَا فِي قَبْرِهَا أَنَا ‏ ‏وَابْنُ عَبَّاسٍ ‏","","",""],[25599,25599,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعْدُ بْنُ أَوْسٍ ‏ ‏عَنْ ‏ ‏بِلَالٍ الْعَبْسِيِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ ‏ ‏كَيْفَ أَنْتُمْ إِذَا ‏ ‏مَرِجَ ‏ ‏الدِّينُ وَظَهَرَتْ الرَّغْبَةُ وَاخْتَلَفَتْ الْإِخْوَانُ وَحُرِّقَ ‏ ‏الْبَيْتُ الْعَتِيقُ ‏","","",""],[25600,25600,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ لَبِيبَةَ بْنِ عُبَيْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ أُمَّتِي بِخَيْرٍ مَا لَمْ يَفْشُ فِيهِمْ وَلَدُ الزِّنَا فَإِذَا فَشَا فِيهِمْ وَلَدُ الزِّنَا فَيُوشِكُ أَنْ يَعُمَّهُمْ اللَّهُ عَزَّ وَجَلَّ بِعِقَابٍ ‏","","",""]];
